CREATE OR REPLACE FUNCTION meetany_private.admin_page_cursor(p_cursor jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_time timestamptz;
  v_id uuid;
  v_asof timestamptz := statement_timestamp();
begin
  if p_cursor is null then return jsonb_build_object('asOf',v_asof); end if;
  if jsonb_typeof(p_cursor) <> 'object' or not (p_cursor ?& array['created_at','id','asOf']) then
    raise exception using errcode = '22023', message = 'invalid admin cursor';
  end if;
  begin
    v_time := (p_cursor->>'created_at')::timestamptz;
    v_id := (p_cursor->>'id')::uuid;
    v_asof := (p_cursor->>'asOf')::timestamptz;
  exception when others then
    raise exception using errcode = '22023', message = 'invalid admin cursor';
  end;
  if v_time is null or v_id is null or v_asof is null or not isfinite(v_time) or not isfinite(v_asof)
     or v_time > v_asof or v_asof > statement_timestamp() then
    raise exception using errcode = '22023', message = 'invalid admin cursor';
  end if;
  return jsonb_build_object('created_at',v_time,'id',v_id,'asOf',v_asof);
end $function$

CREATE OR REPLACE FUNCTION meetany_private.check_terms(p_quantity numeric, p_unit text, p_needed_by date, p_keep_date date DEFAULT NULL::date, OUT quantity numeric, OUT unit text)
 RETURNS record
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
begin
  if p_quantity is not null then
    if p_quantity = 'NaN'::numeric or p_quantity <= 0 or p_quantity > 1000000000 then perform meetany_private.fail('MA111'); end if;
    quantity := round(p_quantity, 3);
    if quantity <= 0 then perform meetany_private.fail('MA111'); end if;
    if not meetany_private.is_unit(p_unit) then perform meetany_private.fail('MA112'); end if;
    unit := p_unit;
  end if;
  if p_needed_by is not null and p_needed_by is distinct from p_keep_date
     and (p_needed_by < meetany_private.today()
          or p_needed_by > (meetany_private.today() + interval '2 years')::date) then
    perform meetany_private.fail('MA113');
  end if;
end
$function$

CREATE OR REPLACE FUNCTION meetany_private.claim_notification_email(p_from text, p_origin text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare job meetany_private.notification_outbox; event meetany_private.notifications; recipient public.profiles; message text;
begin
 if p_origin !~ '^https://[^/]+$' or p_from is null or length(p_from)<5 then raise exception using errcode='22023',message='invalid email configuration'; end if;
 -- Re-check consent, visibility and verified identity before every attempt.
 update meetany_private.notification_outbox o set status='cancelled',lease_id=null,locked_until=null
 where o.status in ('pending','processing') and not exists (
  select 1 from meetany_private.notifications n join public.profiles p on p.id=n.user_id and not p.blocked
  join neon_auth."user" u on u.id=p.id and u."emailVerified"=true
  join public.requests r on r.id=n.request_id and not r.hidden
  join meetany_private.notification_preferences pref on pref.user_id=p.id and pref.email_offers
  where n.id=o.notification_id
 );
 update meetany_private.notification_outbox set status='failed',last_error='retry_limit',lease_id=null,locked_until=null
 where status in ('pending','processing') and (attempts>=8 or first_attempt_at<now()-interval '23 hours')
 and (locked_until is null or locked_until<=now());
 select * into job from meetany_private.notification_outbox
 where ((status='pending' and available_at<=now()) or (status='processing' and locked_until<=now()))
 and attempts<8 order by available_at,id for update skip locked limit 1;
 if not found then return null; end if;
 select * into event from meetany_private.notifications where id=job.notification_id;
 select * into recipient from public.profiles where id=event.user_id;
 message:=case when event.kind='offer_chosen' then 'შენი შეთავაზება აირჩიეს' else 'ახალი შეთავაზება მიიღე' end;
 update meetany_private.notification_outbox set status='processing',attempts=attempts+1,lease_id=gen_random_uuid(),locked_until=now()+interval '2 minutes',
 first_attempt_at=coalesce(first_attempt_at,now()),
 payload=coalesce(payload,jsonb_build_object('from',p_from,'to',jsonb_build_array(recipient.email),'subject','MeetAny · '||message,
 'text',message||E'\n\n'||p_origin||'/requests/view/?id='||event.request_id::text||E'\n\nშეტყობინებების პარამეტრები: '||p_origin||'/account/?tab=notifications'))
 where id=job.id returning * into job;
 return jsonb_build_object('id',job.id,'lease',job.lease_id,'payload',job.payload);
end $function$

CREATE OR REPLACE FUNCTION meetany_private.claim_request_alert_email(p_from text, p_origin text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare job meetany_private.request_alert_emails; ids uuid[]; body text; recipient_email text; title text;
begin
 if p_origin !~ '^https://[^/]+$' or p_from is null or length(p_from)<5 then raise exception using errcode='22023',message='invalid email configuration'; end if;
 update meetany_private.request_alert_emails j set status='cancelled',lease_id=null,locked_until=null
 where j.status in ('pending','processing') and not exists (
  select 1 from meetany_private.request_alert_preferences pref join public.profiles p on p.id=pref.user_id and p.role='company' and not p.blocked
  join neon_auth."user" u on u.id=p.id and u."emailVerified"=true
  where pref.user_id=j.user_id and pref.enabled and pref.email_mode=j.mode
 );
 update meetany_private.request_alert_emails set status='failed',last_error='retry_limit',lease_id=null,locked_until=null
 where status in ('pending','processing') and (attempts>=8 or first_attempt_at<now()-interval '23 hours') and (locked_until is null or locked_until<=now());
 for job in select * from meetany_private.request_alert_emails
  where (status='pending' and available_at<=now()) or (status='processing' and locked_until<=now())
  order by available_at,id for update skip locked limit 50
 loop
  select array_agg(n.id order by n.id),string_agg(
   r.title||E'\n'||coalesce('{"tbilisi":"თბილისი","batumi":"ბათუმი","kutaisi":"ქუთაისი","rustavi":"რუსთავი","zugdidi":"ზუგდიდი","telavi":"თელავი","gori":"გორი","georgia":"მთელი საქართველო"}'::jsonb->>r.city,r.city)
   ||case when r.needed_by is not null then ' · საჭიროა '||to_char(r.needed_by,'DD.MM.YYYY') else '' end
   ||E'\n'||p_origin||'/requests/view/?id='||r.id::text,E'\n\n' order by n.created_at,n.id)
  into ids,body
  from meetany_private.request_alert_email_items i join meetany_private.notifications n on n.id=i.notification_id
  join public.requests r on r.id=n.request_id
  join public.profiles owner on owner.id=r.owner_id and not owner.blocked
  join meetany_private.request_alert_preferences pref on pref.user_id=n.user_id
  where i.job_id=job.id and meetany_private.request_state(r)='open'
   and r.category=any(pref.categories) and (r.city='georgia' or 'georgia'=any(pref.cities) or r.city=any(pref.cities));
  -- A retry cannot change provider content. If a request disappeared, cancel the frozen batch.
  if ids is null or (job.payload is not null and ids is distinct from job.frozen_ids) then
   update meetany_private.request_alert_emails set status='cancelled',lease_id=null,locked_until=null where id=job.id;
   continue;
  end if;
  select email into recipient_email from public.profiles where id=job.user_id;
  title:=case when job.mode='daily' then 'ახალი მოთხოვნების დღის შეჯამება ('||cardinality(ids)||')' else 'შენთვის ახალი მოთხოვნა გამოქვეყნდა' end;
  update meetany_private.request_alert_emails set status='processing',attempts=attempts+1,lease_id=gen_random_uuid(),locked_until=now()+interval '2 minutes',first_attempt_at=coalesce(first_attempt_at,now()),
   frozen_ids=coalesce(frozen_ids,ids),payload=coalesce(payload,jsonb_build_object('from',p_from,'to',jsonb_build_array(recipient_email),'subject','MeetAny · '||title,
   'text',title||E'\n\n'||body||E'\n\nშეტყობინებების გამორთვა ან შეცვლა: '||p_origin||'/account/?tab=notifications'))
  where id=job.id returning * into job;
  return jsonb_build_object('id',job.id,'lease',job.lease_id,'payload',job.payload);
 end loop;
 return null;
end $function$

CREATE OR REPLACE FUNCTION meetany_private.file_scope(p_kind text, p_target uuid, p_write boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me uuid:=meetany_private.uid(); admin boolean:=meetany_private.is_admin();
begin
 if p_write and not meetany_private.can_write() then return false; end if;
 if me is not null and exists(select 1 from public.profiles where id=me and blocked) then return false; end if;
 if not p_write and admin then return true; end if;
 case p_kind
 when 'request_draft','offer_draft' then return p_write and me is not null;
 when 'verification' then return exists(select 1 from public.profiles where id=p_target and id=me and role='company' and not blocked and (not p_write or verification_documents_status not in('pending','approved')));
 when 'request' then return exists(select 1 from public.requests r join public.profiles p on p.id=r.owner_id where r.id=p_target and not p.blocked and
 (case when p_write then r.owner_id=me and meetany_private.request_state(r)='open' and not r.hidden else (not r.hidden or r.owner_id=me) end));
 when 'offer' then return exists(select 1 from public.offers o join public.requests r on r.id=o.request_id join public.profiles p on p.id=o.company_id where o.id=p_target and not p.blocked and
 (case when p_write then o.company_id=me and meetany_private.request_state(r)='open' and not r.hidden else me in(o.company_id,r.owner_id) end));
 when 'conversation' then return exists(select 1 from meetany_private.conversations c join public.profiles p on p.id=c.company_id join public.profiles b on b.id=c.client_id where c.id=p_target and me in(c.client_id,c.company_id) and not p.blocked and not b.blocked);
 when 'deal','issue' then return exists(select 1 from meetany_private.deals d join public.profiles p on p.id=d.supplier_id join public.profiles b on b.id=d.buyer_id where d.id=p_target and me in(d.buyer_id,d.supplier_id) and not p.blocked and not b.blocked and (not p_write or d.stage in('progress','complete')));
 else return false;
 end case;
end $function$

CREATE OR REPLACE FUNCTION meetany_private.guard_deal_collaboration()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare previous jsonb:=to_jsonb(old); original_price numeric;
begin
 if old.total_price is null then
  select case when o.price_type='total' then o.price when o.price_type='unit' then o.price*r.quantity else null end into original_price from public.offers o join public.requests r on r.id=o.request_id where o.id=old.offer_id;
  previous:=previous||jsonb_build_object('total_price',original_price);
 end if;
 if exists(select 1 from meetany_private.deal_issues where deal_id=old.id and status='open') and (new.stage is distinct from old.stage or new.rating is distinct from old.rating) then perform meetany_private.flow_fail('MA903'); end if;
 if new.stage='terms' and (old.stage<>'terms' or (new.total_price,new.quantity,new.unit,new.delivery_days,new.delivery_date,new.delivery_place,new.payment_terms,new.includes) is distinct from (old.total_price,old.quantity,old.unit,old.delivery_days,old.delivery_date,old.delivery_place,old.payment_terms,old.includes)) then
  update meetany_private.deal_proposals set status='superseded' where deal_id=new.id and status='pending';
  insert into meetany_private.deal_proposals(deal_id,revision,actor_id,previous,proposed) values(new.id,new.revision,meetany_private.uid(),previous,to_jsonb(new));
 end if;
 if new.buyer_confirmed_at is not null and new.supplier_confirmed_at is not null then update meetany_private.deal_proposals set status='accepted' where deal_id=new.id and status='pending'; end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION meetany_private.messaging_context_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if (new.client_id,new.company_id,new.context_key) is distinct from (old.client_id,old.company_id,old.context_key)
 or (new.request_id is distinct from old.request_id and new.request_id is not null) then
  perform meetany_private.fail('MA507');
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION meetany_private.normalize_phone(p text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  d text := regexp_replace(coalesce(p, ''), '[^0-9]', '', 'g');
  l text;
begin
  if left(d, 3) = '995' then l := substr(d, 4);
  elsif left(d, 1) = '0' then l := substr(d, 2);
  else l := d;
  end if;
  if l !~ '^5[0-9]{8}$' then return null; end if;
  return '+995 ' || substr(l, 1, 3) || ' ' || substr(l, 4, 3) || ' ' || substr(l, 7, 3);
end
$function$

CREATE OR REPLACE FUNCTION meetany_private.notify_offer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare recipient uuid; target_offer uuid; target_request uuid; event_kind text; event_id uuid;
begin
 if tg_table_name='offers' then
  select owner_id into recipient from public.requests where id=new.request_id;
  target_offer:=new.id; target_request:=new.request_id; event_kind:='offer_received';
 else
  if new.chosen_offer_id is null or new.chosen_offer_id is not distinct from old.chosen_offer_id then return new; end if;
  insert into meetany_private.notifications(user_id,request_id,offer_id,kind)
  select o.company_id,new.id,o.id,'offer_declined' from public.offers o join public.profiles p on p.id=o.company_id and not p.blocked
  where o.request_id=new.id and o.id<>new.chosen_offer_id on conflict do nothing;
  select company_id into recipient from public.offers where id=new.chosen_offer_id;
  target_offer:=new.chosen_offer_id; target_request:=new.id; event_kind:='offer_chosen';
 end if;
 if recipient is null or not exists(select 1 from public.profiles where id=recipient and not blocked) then return new; end if;
 insert into meetany_private.notifications(user_id,request_id,offer_id,kind)
 values(recipient,target_request,target_offer,event_kind) on conflict do nothing returning id into event_id;
 if event_id is not null and exists(select 1 from meetany_private.notification_preferences where user_id=recipient and email_offers) then
  insert into meetany_private.notification_outbox(notification_id) values(event_id) on conflict do nothing;
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION meetany_private.own_request(p_request_id uuid, me profiles)
 RETURNS requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  r public.requests;
begin
  select * into r from public.requests where id = p_request_id for update;
  if not found or (r.hidden and r.owner_id <> me.id and me.role <> 'admin') then
    perform meetany_private.fail('MA106');
  end if;
  if r.owner_id <> me.id and me.role <> 'admin' then perform meetany_private.fail('MA107'); end if;
  return r;
end
$function$

CREATE OR REPLACE FUNCTION meetany_private.photo_origin()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v text;
begin
  select s.value into v from meetany_private.settings s where s.key = 'photo_origin';
  v := lower(rtrim(btrim(coalesce(v, '')), '/'));
  if v !~ '^https?://[a-z0-9]([a-z0-9.-]{0,251}[a-z0-9])?(:[0-9]{1,5})?$' then return null; end if;
  return v;
end
$function$

CREATE OR REPLACE FUNCTION meetany_private.require_conversation(p_id uuid, p_user_id uuid)
 RETURNS meetany_private.conversations
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c meetany_private.conversations;
begin
 select * into c from meetany_private.conversations where id=p_id and p_user_id in (client_id,company_id);
 if not found then perform meetany_private.fail('MA501'); end if;
 return c;
end $function$

CREATE OR REPLACE FUNCTION meetany_private.require_user()
 RETURNS profiles
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  p public.profiles;
begin
  if meetany_private.uid() is null then perform meetany_private.fail('MA001'); end if;
  select * into p from public.profiles where id = meetany_private.uid();
  if not found then perform meetany_private.fail('MA001'); end if;
  if p.blocked then perform meetany_private.fail('MA002'); end if;
  return p;
end
$function$

CREATE OR REPLACE FUNCTION meetany_private.valid_request_preferences(p jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
begin
 if p is null or jsonb_typeof(p)<>'object' or octet_length(p::text)>12000 or exists(select 1 from jsonb_object_keys(p) k where k not in('specification','design','supplierTypes','certificates','verifiedOnly','flexibility','budgetType','budgetMin','budgetMax','budgetPrivate','payment','vatInvoice','deferredPayment')) then return false; end if;
 if exists(select 1 from jsonb_each(p) x where x.key in('specification','design','certificates','payment') and jsonb_typeof(x.value)<>'string') then return false; end if;
 if p ? 'design' and p->>'design' not in('','ready','needed','none') then return false; end if;
 if length(coalesce(p->>'specification',''))>2000 or length(coalesce(p->>'design',''))>120 or length(coalesce(p->>'payment',''))>500 or length(coalesce(p->>'certificates',''))>500 then return false; end if;
 if p ? 'flexibility' then
  if jsonb_typeof(p->'flexibility')<>'number' then return false; end if;
  if (p->>'flexibility')::numeric not between 0 and 30 then return false; end if;
 end if;
 if p ? 'supplierTypes' then
  if jsonb_typeof(p->'supplierTypes')<>'array' then return false; end if;
  if jsonb_array_length(p->'supplierTypes')>3 or exists(select 1 from jsonb_array_elements(p->'supplierTypes') t where jsonb_typeof(t)<>'string' or t#>>'{}' not in('manufacturer','distributor','service')) then return false; end if;
 end if;
 if coalesce(p->>'budgetType','negotiable') not in('range','exact','negotiable') then return false; end if;
 if exists(select 1 from jsonb_each(p) x where x.key in('budgetMin','budgetMax') and jsonb_typeof(x.value)<>'number') then return false; end if;
 if exists(select 1 from jsonb_each(p) x where x.key in('budgetMin','budgetMax') and (x.value::text)::numeric not between 0 and 1000000000) then return false; end if;
 if coalesce(p->>'budgetType','negotiable')<>'negotiable' then
  if not p ? 'budgetMin' then return false; end if;
  if (p->>'budgetMin')::numeric<=0 then return false; end if;
  if p->>'budgetType'='range' and (not p ? 'budgetMax' or (p->>'budgetMax')::numeric<(p->>'budgetMin')::numeric) then return false; end if;
 end if;
 if exists(select 1 from jsonb_each(p) x where x.key in('budgetPrivate','verifiedOnly','vatInvoice','deferredPayment') and jsonb_typeof(x.value)<>'boolean') then return false; end if;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.add_deal_update(p_deal_id uuid, p_expected_revision integer, p_status text, p_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_user(); d meetany_private.deals; u meetany_private.deal_updates;
begin
 select * into d from meetany_private.deals where id=p_deal_id and supplier_id=me.id for update;
 if not found then perform meetany_private.flow_fail('MA901'); end if;
 if p_expected_revision is distinct from d.revision then perform meetany_private.flow_fail('MA904'); end if;
 if d.stage<>'progress' or exists(select 1 from meetany_private.deal_issues where deal_id=d.id and status='open') then perform meetany_private.flow_fail('MA903'); end if;
 if p_status not in('started','producing','ready','delivered') or length(btrim(coalesce(p_body,''))) not between 1 and 2000 then perform meetany_private.flow_fail('MA902'); end if;
 insert into meetany_private.deal_updates(deal_id,actor_id,status,body) values(d.id,me.id,p_status,btrim(p_body)) returning * into u;
 update meetany_private.deals set revision=revision+1 where id=d.id returning * into d;
 perform meetany_private.deal_event(d,'update_'||p_status);
 return to_jsonb(u);
end $function$

CREATE OR REPLACE FUNCTION public.admin_anonymize_user(p_user_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_admin(); old public.profiles; reason text:=meetany_private.moderation_reason(p_reason);
begin
 if reason is null then perform meetany_private.fail('MA304'); end if;
 select * into old from public.profiles where id=p_user_id for update;
 if old.id is null then perform meetany_private.fail('MA302'); end if;
 if old.role='admin' or old.id=me.id then raise exception using message='MA310: administrator cannot be anonymized',hint='MA310'; end if;
 update public.profiles set name='წაშლილი მომხმარებელი',company='',email='deleted-'||id||'@anonymized.meetany.ge',phone='',about='',logo_url=null,gallery='{}',
 address=null,lat=null,lng=null,website=null,legal_name=null,legal_form=null,registration_code=null,contact_position=null,blocked=true,blocked_reason=reason,anonymized_at=coalesce(anonymized_at,now()) where id=old.id;
 update public.requests r set hidden=true,hidden_reason=reason where r.owner_id=old.id and meetany_private.request_state(r)='open';
 update public.offers set status='withdrawn',updated_at=clock_timestamp() where company_id=old.id and status='sent';
 delete from meetany_private.saved_companies where user_id=old.id;
 delete from meetany_private.saved_requests where user_id=old.id;
 delete from meetany_private.request_alert_emails where user_id=old.id;
 delete from meetany_private.request_alert_preferences where user_id=old.id;
 insert into meetany_private.moderation_audit(actor_id,target_type,target_id,action,reason,old_flags,new_flags)
 values(me.id,'user',old.id,'user.anonymize',reason,jsonb_build_object('blocked',old.blocked),jsonb_build_object('blocked',true,'anonymized',true));
end $function$

CREATE OR REPLACE FUNCTION public.admin_apply_contact_change(p_report_id uuid, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 me public.profiles:=meetany_private.require_admin(); r meetany_private.reports;
 old public.profiles; updated public.profiles; v_phone text; v_email text;
 note text:=nullif(btrim(p_note),'');
begin
 select * into r from meetany_private.reports where id=p_report_id for update;
 if r.id is null or r.status<>'new' or r.target_kind<>'contact_change' then perform meetany_private.report_fail('MA706'); end if;
 if note is not null and length(note)>500 then perform meetany_private.fail('MA304'); end if;
 if r.payload is null or jsonb_typeof(r.payload)<>'object' then raise exception using message='MA711: missing contact payload',hint='MA711'; end if;
 select * into old from public.profiles where id=r.target_id for update;
 if old.id is null or r.reporter_id<>old.id then perform meetany_private.fail('MA302'); end if;
 v_phone:=nullif(btrim(r.payload->>'phone'),''); v_email:=nullif(lower(btrim(r.payload->>'email')),'');
 if v_phone is null and v_email is null then raise exception using message='MA711: empty contact payload',hint='MA711'; end if;
 if v_phone is not null then
  v_phone:=meetany_private.normalize_phone(v_phone);
  if v_phone is null then perform meetany_private.fail('MA404'); end if;
  if exists(select 1 from public.profiles where id<>old.id and profiles.phone=v_phone) then perform meetany_private.fail('MA405'); end if;
 end if;
 if v_email is not null and (length(v_email)>200 or v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') then perform meetany_private.fail('MA403'); end if;
 -- Same normalized phone/unique-phone and email-format rules as profile creation.
 -- update_my_profile deliberately cannot edit contact identifiers. Neon Auth is never updated here.
 begin
  update public.profiles set phone=coalesce(v_phone,old.phone),email=coalesce(v_email,old.email) where id=old.id returning * into updated;
 exception when unique_violation then perform meetany_private.fail('MA405');
 end;
 update meetany_private.reports set status='handled',resolution='applied',resolution_reason=note,handled_by=me.id,handled_at=now() where id=r.id;
 insert into meetany_private.moderation_audit(actor_id,target_type,target_id,action,reason,old_flags,new_flags)
 values(me.id,'user',old.id,'edit_profile',note,jsonb_build_object('phone',old.phone,'email',old.email),jsonb_build_object('phone',updated.phone,'email',updated.email));
 insert into meetany_private.business_audit(actor_id,target_id,action,detail) values(me.id,r.id,'contact_change_applied',jsonb_build_object('target_id',old.id,'reason',note));
 perform meetany_private.account_notice(r.reporter_id,'report_resolved',jsonb_build_object('title','კონტაქტის შეცვლის მოთხოვნა','resolution','საკონტაქტო მონაცემები განახლდა. შესასვლელი ელფოსტა უცვლელია.','resolution_reason',note,'report_id',r.id,'kind',r.target_kind));
 return jsonb_build_object('id',r.id,'status','handled','resolution','applied');
end $function$

CREATE OR REPLACE FUNCTION public.admin_business_queue(p_kind text, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 perform meetany_private.require_admin();
 if p_offset is null or p_offset<0 or p_kind is null or p_kind not in ('reviews','plans') then raise exception using errcode='22023',message='invalid queue'; end if;
 if p_kind='reviews' then
 return jsonb_build_object('total',(select count(*) from meetany_private.company_reviews),'items',(select coalesce(jsonb_agg(to_jsonb(t)),'[]') from (
 select v.*,p.company,a.name author from meetany_private.company_reviews v join public.profiles p on p.id=v.company_id join public.profiles a on a.id=v.author_id
 order by (v.status='pending') desc,v.updated_at desc,v.id limit 20 offset p_offset) t));
 end if;
 return jsonb_build_object('total',(select count(*) from meetany_private.plan_requests),'items',(select coalesce(jsonb_agg(to_jsonb(t)),'[]') from (
 select v.*,p.company,p.email,p.phone,m.plan active_plan,m.expires_at from meetany_private.plan_requests v join public.profiles p on p.id=v.company_id
 left join meetany_private.company_plans m on m.company_id=p.id
 order by (v.status='pending') desc,v.updated_at desc,v.id limit 20 offset p_offset) t));
end $function$

