CREATE OR REPLACE FUNCTION public.admin_edit_offer(p_id uuid, p_patch jsonb, p_reason text)
 RETURNS offers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_admin(); old public.offers; updated public.offers; reason text:=meetany_private.moderation_reason(p_reason); old_diff jsonb; new_diff jsonb;
begin
 if reason is null then perform meetany_private.fail('MA304'); end if;
 if p_patch is null or jsonb_typeof(p_patch)<>'object' or p_patch='{}'::jsonb then raise exception using message='MA311: invalid offer patch',hint='MA311'; end if;
 if exists(select 1 from jsonb_object_keys(p_patch) k where k<>all(array['body','price','price_type','vat_included','delivery_days','delivery_included','payment_terms','valid_until','commercial_terms'])) then raise exception using message='MA311: invalid offer patch key',hint='MA311'; end if;
 select * into old from public.offers where id=p_id for update;
 if old.id is null then perform meetany_private.flow_fail('MA901'); end if;
 updated:=jsonb_populate_record(old,p_patch);
 updated.body:=rtrim(left(btrim(coalesce(updated.body,'')),2000));
 if length(updated.body)<10 then perform meetany_private.fail('MA204'); end if;
 if updated.price_type is null or updated.price_type not in ('unit','total','negotiable') then perform meetany_private.fail('MA210'); end if;
 if updated.price_type='negotiable' and updated.price is not null then perform meetany_private.fail('MA211'); end if;
 if updated.price_type<>'negotiable' and updated.price is null then perform meetany_private.fail('MA212'); end if;
 if updated.price is not null and (updated.price='NaN'::numeric or updated.price<=0 or updated.price>1000000000) then perform meetany_private.fail('MA205'); end if;
 if updated.delivery_days is not null and updated.delivery_days not between 0 and 365 then perform meetany_private.fail('MA213'); end if;
 if (updated.payment_terms is not null and length(btrim(updated.payment_terms)) not between 1 and 500)
 or (p_patch ? 'valid_until' and updated.valid_until is not null and (not isfinite(updated.valid_until) or updated.valid_until<meetany_private.today()))
 or updated.commercial_terms is null or not meetany_private.valid_items(updated.commercial_terms) then perform meetany_private.flow_fail('MA902'); end if;
 updated.vat_included:=updated.price_type<>'negotiable' and coalesce(updated.vat_included,false);
 updated.delivery_included:=coalesce(updated.delivery_included,false);
 updated.payment_terms:=btrim(updated.payment_terms);
 update public.offers set body=updated.body,price=updated.price,price_type=updated.price_type,vat_included=updated.vat_included,delivery_days=updated.delivery_days,delivery_included=updated.delivery_included,payment_terms=updated.payment_terms,valid_until=updated.valid_until,commercial_terms=updated.commercial_terms,updated_at=clock_timestamp() where id=old.id returning * into updated;
 select coalesce(jsonb_object_agg(k,to_jsonb(old)->k),'{}'),coalesce(jsonb_object_agg(k,to_jsonb(updated)->k),'{}') into old_diff,new_diff
 from unnest(array['body','price','price_type','vat_included','delivery_days','delivery_included','payment_terms','valid_until','commercial_terms']) k where to_jsonb(old)->k is distinct from to_jsonb(updated)->k;
 insert into meetany_private.moderation_audit(actor_id,target_type,target_id,action,reason,old_flags,new_flags) values(me.id,'offer',old.id,'offer.edit',reason,old_diff,new_diff);
 return updated;
end $function$

CREATE OR REPLACE FUNCTION public.admin_edit_profile(p_id uuid, p_patch jsonb)
 RETURNS profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_admin(); old public.profiles; v public.profiles; k text; origin text:=meetany_private.photo_origin();
begin
 select * into old from public.profiles where id=p_id for update;
 if not found then perform meetany_private.fail('MA302'); end if;
 if p_patch is null or jsonb_typeof(p_patch)<>'object' then raise exception using errcode='22023',message='invalid profile'; end if;
 for k in select jsonb_object_keys(p_patch) loop
 if k<>all(array['name','company','phone','city','industry','about','address','lat','lng','logo_url','gallery','offers','seeks','service_cities',
   'legal_name','registration_code','legal_form','website','founded_year','employee_band','contact_position','account_intent']) then raise exception using errcode='22023',message='unsupported profile field'; end if;
 end loop;
 v:=jsonb_populate_record(old,p_patch);
 if v.lat is not null and (v.lat not between -90 and 90 or v.lng is null or v.lng not between -180 and 180) or (v.lat is null and v.lng is not null) then perform meetany_private.fail('MA413'); end if;
 if v.logo_url is not null and (origin is null or not meetany_private.valid_photo_url(v.logo_url,p_id) or lower(left(v.logo_url,length(origin)+1))<>origin||'/' or substr(v.logo_url,length(origin)+2,42)<>p_id::text||'/logo-') then perform meetany_private.fail('MA115'); end if;
 if exists(select 1 from unnest(v.gallery) u where origin is null or lower(left(u,length(origin)+1))<>origin||'/' or substr(u,length(origin)+2,45)<>p_id::text||'/gallery-') then perform meetany_private.fail('MA116'); end if;
 update public.profiles set name=btrim(v.name),company=btrim(v.company),phone=v.phone,city=v.city,industry=v.industry,about=btrim(v.about),address=nullif(btrim(v.address),''),lat=v.lat,lng=v.lng,logo_url=v.logo_url,gallery=v.gallery,offers=v.offers,seeks=v.seeks,service_cities=v.service_cities,
   legal_name=nullif(btrim(v.legal_name),''),registration_code=nullif(btrim(v.registration_code),''),legal_form=nullif(btrim(v.legal_form),''),
   website=nullif(btrim(v.website),''),founded_year=v.founded_year,employee_band=nullif(v.employee_band,''),contact_position=nullif(btrim(v.contact_position),''),
   account_intent=coalesce(nullif(v.account_intent,''),old.account_intent)
  where id=p_id returning * into v;
 insert into meetany_private.moderation_audit(actor_id,target_type,target_id,action,old_flags,new_flags) values(me.id,'user',p_id,'edit_profile',to_jsonb(old),to_jsonb(v));
 return v;
end $function$

CREATE OR REPLACE FUNCTION public.admin_edit_request(p_id uuid, p_patch jsonb)
 RETURNS requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_admin(); old public.requests; v public.requests; k text; origin text:=meetany_private.photo_origin();
begin
 select * into old from public.requests where id=p_id for update;
 if not found then perform meetany_private.fail('MA106'); end if;
 if p_patch is null or jsonb_typeof(p_patch)<>'object' then raise exception using errcode='22023',message='invalid request'; end if;
 for k in select jsonb_object_keys(p_patch) loop
 if k<>all(array['title','body','category','city','address_note','quantity','unit','needed_by','photo_url','status','expires_at']) then raise exception using errcode='22023',message='unsupported request field'; end if;
 end loop;
 v:=jsonb_populate_record(old,p_patch);
 perform meetany_private.check_terms(v.quantity,v.unit,v.needed_by,old.needed_by);
 if v.chosen_offer_id is not null and v.status='open' and old.status<>'open' then raise exception using errcode='22023',message='chosen request cannot reopen'; end if;
 if v.expires_at is null or v.expires_at>now()+interval '2 years' then raise exception using errcode='22023',message='invalid expiry'; end if;
 if v.photo_url is not null and (origin is null or not meetany_private.valid_photo_url(v.photo_url,old.owner_id) or lower(left(v.photo_url,length(origin)+1))<>origin||'/') then perform meetany_private.fail('MA109'); end if;
 update public.requests set title=btrim(v.title),body=btrim(v.body),category=v.category,city=v.city,address_note=nullif(btrim(v.address_note),''),quantity=v.quantity,unit=v.unit,needed_by=v.needed_by,photo_url=v.photo_url,status=v.status,expires_at=v.expires_at where id=p_id returning * into v;
 insert into meetany_private.moderation_audit(actor_id,target_type,target_id,action,old_flags,new_flags) values(me.id,'request',p_id,'edit_request',to_jsonb(old),to_jsonb(v));
 return v;
end $function$

CREATE OR REPLACE FUNCTION public.admin_list_audit(p_cursor jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  me public.profiles := meetany_private.require_admin();
  v_cursor jsonb := meetany_private.admin_page_cursor(p_cursor);
  v_asof timestamptz := (v_cursor->>'asOf')::timestamptz;
  v_limit integer := least(coalesce(p_limit,25),100);
  result jsonb;
begin
  if v_limit < 1 then raise exception using errcode = '22023', message = 'limit must be positive'; end if;
  with source as (select a.* from meetany_private.moderation_audit a),
  filtered as materialized (
    select * from source x where x.created_at <= v_asof and true
  ), candidates as (
    select * from filtered x
    where p_cursor is null or (x.created_at,x.id) < ((v_cursor->>'created_at')::timestamptz,(v_cursor->>'id')::uuid)
    order by x.created_at desc,x.id desc limit v_limit+1
  ), page as (select * from candidates order by created_at desc,id desc limit v_limit)
  select jsonb_build_object(
    'items',coalesce((select jsonb_agg(to_jsonb(p) order by p.created_at desc,p.id desc) from page p),'[]'::jsonb),
    'hasMore',(select count(*)>v_limit from candidates),
    'nextCursor',case when (select count(*)>v_limit from candidates) then
      (select jsonb_build_object('created_at',created_at,'id',id,'asOf',v_asof) from page order by created_at,id limit 1) end,
    'filteredTotal',(select count(*) from filtered),'asOf',v_asof) into result;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_manage_plan(p_id uuid, p_plan text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_admin(); old jsonb;
begin
 if not exists(select 1 from public.profiles where id=p_id and role='company' and not blocked for update) then perform meetany_private.fail('MA302'); end if;
 select to_jsonb(m) into old from meetany_private.company_plans m where company_id=p_id;
 if p_plan is null then delete from meetany_private.company_plans where company_id=p_id;
 else
 if p_plan not in ('premium','vip') or p_expires_at is null or p_expires_at<=now() or p_expires_at>now()+interval '2 years' then raise exception using errcode='22023',message='invalid plan or expiry'; end if;
 insert into meetany_private.company_plans(company_id,plan,expires_at) values(p_id,p_plan,p_expires_at) on conflict(company_id) do update set plan=excluded.plan,expires_at=excluded.expires_at,updated_at=now();
 end if;
 update meetany_private.plan_requests set status=case when p_plan is null then 'cancelled' else 'approved' end,updated_at=now() where company_id=p_id and status='pending';
 insert into meetany_private.business_audit(actor_id,target_id,action,detail) values(me.id,p_id,'plan_managed',jsonb_build_object('old',old,'plan',p_plan,'expires_at',p_expires_at));
 return public.admin_company_settings(p_id);
end $function$

CREATE OR REPLACE FUNCTION public.admin_moderate_review(p_id uuid, p_status text, p_reason text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_admin();
begin
 if p_status is null or p_status not in ('published','hidden') or length(coalesce(p_reason,''))>500 or (p_status='hidden' and length(btrim(coalesce(p_reason,'')))<3) then
 raise exception using errcode='22023',message='MA603: add moderation reason'; end if;
 update meetany_private.company_reviews set status=p_status,reason=btrim(coalesce(p_reason,'')),updated_at=now() where id=p_id;
 if not found then perform meetany_private.fail('MA302'); end if;
 insert into meetany_private.business_audit(actor_id,target_id,action,detail) values(me.id,p_id,'review_'||p_status,jsonb_build_object('reason',p_reason));
end $function$

CREATE OR REPLACE FUNCTION public.admin_overview()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare today date:=(now() at time zone 'Asia/Tbilisi')::date; cutoff timestamptz:=((today-59)::timestamp at time zone 'Asia/Tbilisi');
begin
 perform meetany_private.require_admin();
 return jsonb_build_object(
  'generatedAt',now(),
  'stats',public.admin_stats(),
  'activity',(
   with request_days as (
    select (r.created_at at time zone 'Asia/Tbilisi')::date as day_key,count(*) n from public.requests r
    where r.created_at>=cutoff and r.created_at<=now() and not r.hidden group by 1
   ), registration_days as (
    select (p.created_at at time zone 'Asia/Tbilisi')::date as day_key,count(*) n from public.profiles p
    where p.created_at>=cutoff and p.created_at<=now() and p.role<>'admin' group by 1
   )
   select jsonb_agg(jsonb_build_object('day',to_char(today-(59-s.i),'YYYY-MM-DD'),'requests',coalesce(r.n,0),'registrations',coalesce(p.n,0)) order by s.i)
   from generate_series(0,59) s(i) left join request_days r on r.day_key=today-(59-s.i) left join registration_days p on p.day_key=today-(59-s.i)
  ),
  'pending',jsonb_build_object(
   'total',(select count(*) from public.profiles where role='company' and not verified and not blocked),
   'items',(select coalesce(jsonb_agg(to_jsonb(q)-'created_at' order by q.created_at,q.id),'[]'::jsonb) from (
    select id,name,company,industry,created_at from public.profiles where role='company' and not verified and not blocked order by created_at,id limit 6
   ) q)
  ),
  'unanswered',jsonb_build_object(
   'total',(select count(*) from public.requests r where not r.hidden and r.status='open' and r.chosen_offer_id is null and r.expires_at>now() and r.created_at<now()-interval '3 days' and not exists(select 1 from public.offers o where o.request_id=r.id)),
   'items',(select coalesce(jsonb_agg(to_jsonb(q) order by q."createdAt",q.id),'[]'::jsonb) from (
    select r.id,r.title,r.category,r.created_at "createdAt",0 "offerCount",ceil(greatest(0,extract(epoch from r.expires_at-now()))/86400)::integer "daysLeft"
    from public.requests r where not r.hidden and r.status='open' and r.chosen_offer_id is null and r.expires_at>now() and r.created_at<now()-interval '3 days' and not exists(select 1 from public.offers o where o.request_id=r.id)
    order by r.created_at,r.id limit 6
   ) q)
  ),
  'expiring',jsonb_build_object(
   'total',(select count(*) from public.requests r where not r.hidden and r.status='open' and r.chosen_offer_id is null and r.expires_at>now() and r.expires_at<=now()+interval '2 days'),
   'items',(select coalesce(jsonb_agg(to_jsonb(q) order by q."expiresAt",q.id),'[]'::jsonb) from (
    select r.id,r.title,r.category,r.created_at "createdAt",r.expires_at "expiresAt",(select count(*)::integer from public.offers o where o.request_id=r.id) "offerCount",ceil(greatest(0,extract(epoch from r.expires_at-now()))/86400)::integer "daysLeft"
    from public.requests r where not r.hidden and r.status='open' and r.chosen_offer_id is null and r.expires_at>now() and r.expires_at<=now()+interval '2 days'
    order by r.expires_at,r.id limit 6
   ) q)
  )
 );
end $function$

CREATE OR REPLACE FUNCTION public.admin_remove_company_photo(p_user_id uuid, p_url text, p_reason text)
 RETURNS profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  me public.profiles := meetany_private.require_admin();
  v_reason text := meetany_private.moderation_reason(p_reason);
  v_url text := btrim(coalesce(p_url, ''));
  previous public.profiles;
  v_field text;
  p public.profiles;
begin
  if v_reason is null then perform meetany_private.fail('MA304'); end if;
  select * into previous from public.profiles where id = p_user_id for update;
  if not found then perform meetany_private.fail('MA302'); end if;
  if v_url <> '' and previous.logo_url = v_url then v_field := 'logo';
  elsif v_url <> '' and v_url = any (previous.gallery) then v_field := 'gallery';
  else perform meetany_private.fail('MA305'); end if;
  update public.profiles
     set logo_url = case when v_field = 'logo' then null else logo_url end,
         gallery = case when v_field = 'gallery' then array_remove(gallery, v_url) else gallery end
   where id = p_user_id
  returning * into p;
  insert into meetany_private.moderation_audit (actor_id,target_type,target_id,action,reason,old_flags,new_flags)
  values (me.id,'user',p_user_id,'user.photo_remove',v_reason,
    jsonb_build_object('field',v_field,'url',v_url),jsonb_build_object('field',v_field,'removed',true));
  return p;
end $function$

CREATE OR REPLACE FUNCTION public.admin_resolve_deal_issue(p_issue_id uuid, p_resolution text, p_outcome text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_admin(); i meetany_private.deal_issues; d meetany_private.deals; previous text;
begin
 if p_outcome is null or p_outcome not in ('resolved','rejected','cancelled') then perform meetany_private.flow_fail('MA902'); end if;
 select * into i from meetany_private.deal_issues where id=p_issue_id;
 if not found then perform meetany_private.flow_fail('MA901'); end if;
 select * into d from meetany_private.deals where id=i.deal_id for update;
 if length(btrim(coalesce(p_resolution,''))) not between 3 and 2000 then perform meetany_private.flow_fail('MA902'); end if;
 if p_outcome='cancelled' and d.stage in ('complete','cancelled') then perform meetany_private.flow_fail('MA903'); end if;
 update meetany_private.deal_issues set status='resolved',outcome=p_outcome,resolved_at=now(),resolved_by=me.id,resolution=btrim(p_resolution) where id=i.id and status='open';
 if not found then return; end if;
 previous:=d.stage;
 update meetany_private.deals set revision=revision+1 where id=d.id returning * into d;
 perform meetany_private.deal_event(d,'issue_resolved');
 if p_outcome='cancelled' then
  update meetany_private.deals set stage='cancelled',cancelled_at=now(),revision=revision+1 where id=d.id returning * into d;
  perform meetany_private.deal_event(d,'cancelled');
 end if;
 insert into meetany_private.moderation_audit(actor_id,target_type,target_id,action,reason,old_flags,new_flags)
 values(me.id,'deal',d.id,'deal.issue_resolve',left(btrim(p_resolution),500),
  jsonb_build_object('issue_id',i.id,'stage',previous,'request_id',d.request_id),
  jsonb_build_object('issue_id',i.id,'outcome',p_outcome,'stage',d.stage,'request_id',d.request_id));
end $function$

CREATE OR REPLACE FUNCTION public.admin_resolve_plan(p_id uuid, p_approve boolean, p_days integer DEFAULT 30, p_note text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_admin(); v meetany_private.plan_requests;
begin
 if p_approve is null or p_days is null or p_days not between 1 and 366 or length(coalesce(p_note,''))>500 then raise exception using errcode='22023',message='invalid plan resolution'; end if;
 select * into v from meetany_private.plan_requests where id=p_id for update;
 if v.id is null or v.status<>'pending' then raise exception using errcode='22023',message='MA604: application already processed'; end if;
 if not exists(select 1 from public.profiles where id=v.company_id and role='company' and not blocked) then perform meetany_private.fail('MA302'); end if;
 update meetany_private.plan_requests set status=case when p_approve then 'approved' else 'declined' end,note=coalesce(p_note,''),updated_at=now() where id=p_id;
 if p_approve then
 insert into meetany_private.company_plans(company_id,plan,expires_at) values(v.company_id,v.plan,now()+make_interval(days=>p_days))
 on conflict(company_id) do update set plan=excluded.plan,expires_at=excluded.expires_at,updated_at=now();
 end if;
 insert into meetany_private.business_audit(actor_id,target_id,action,detail) values(me.id,p_id,'plan_resolved',jsonb_build_object('approved',p_approve,'days',p_days,'plan',v.plan,'note',p_note));
end $function$

CREATE OR REPLACE FUNCTION public.admin_resolve_report(p_id uuid, p_action text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 me public.profiles:=meetany_private.require_admin();
 v_reason text:=meetany_private.moderation_reason(p_reason);
 v meetany_private.reports; c meetany_private.reports; v_effect text:='none'; v_closed integer;
begin
 if v_reason is null then perform meetany_private.fail('MA304'); end if;
 if p_action is null or p_action not in ('hide','reject','hide_review','block_user','dismiss') then raise exception using errcode='22023',message='invalid report action'; end if;
 select * into v from meetany_private.reports where id=p_id for update;
 if v.id is null or v.status<>'new' then perform meetany_private.report_fail('MA706'); end if;
 if (p_action='hide_review' and v.target_kind<>'review') or (p_action='block_user' and v.target_kind<>'conversation')
 or (v.target_kind='review' and p_action not in ('hide_review','dismiss','reject'))
 or (v.target_kind='conversation' and p_action not in ('block_user','dismiss','reject')) then raise exception using errcode='22023',message='invalid resolution for report kind'; end if;
 if p_action='dismiss' then p_action:='reject'; end if;
 if p_action in ('hide_review','block_user') then p_action:='hide'; end if;
 if v.target_kind='contact_change' and p_action<>'reject' then raise exception using errcode='22023',message='use admin_apply_contact_change'; end if;
 if p_action='hide' then
  if v.target_kind='review' then
   perform public.admin_moderate_review(v.target_id,'hidden',v_reason); v_effect:='review.hide';
  elsif v.target_kind='conversation' then
   perform public.admin_set_blocked(v.target_owner_id,true,v_reason); v_effect:='user.block';
  elsif v.target_kind='request' then
   if exists(select 1 from public.requests where id=v.target_id and not hidden) then
    perform public.admin_set_hidden(v.target_id,true,v_reason); v_effect:='request.hide'; end if;
  elsif v.target_kind='offer' then
   if exists(select 1 from public.offers where id=v.target_id) then
    perform public.admin_delete_offer(v.target_id,v_reason); v_effect:='offer.delete'; end if;
  elsif v.target_kind='company' then
   if exists(select 1 from public.profiles where id=v.target_id and not blocked and role<>'admin') then
    perform public.admin_set_blocked(v.target_id,true,v_reason); v_effect:='user.block'; end if;
  end if;
  v_closed:=0;
  for c in update meetany_private.reports set status='handled',resolution='hidden',resolution_reason=v_reason,handled_by=me.id,handled_at=now()
   where target_kind=v.target_kind and target_id=v.target_id and status='new' returning * loop
   perform meetany_private.account_notice(c.reporter_id,'report_resolved',jsonb_build_object('title',coalesce(nullif(c.target_label,''),'საჩივარი'),'resolution','hidden','resolution_reason',left(v_reason,500),'result','hidden','note',left(v_reason,500),'report_id',c.id,'kind',c.target_kind));
   v_closed:=v_closed+1;
  end loop;
 else
  update meetany_private.reports set status='handled',resolution='rejected',resolution_reason=v_reason,handled_by=me.id,handled_at=now()
  where id=v.id;
  get diagnostics v_closed=row_count;
  perform meetany_private.account_notice(v.reporter_id,'report_resolved',jsonb_build_object('title',coalesce(nullif(v.target_label,''),'საჩივარი'),'resolution',case when v.target_kind='contact_change' then 'კონტაქტის შეცვლის მოთხოვნა უარყოფილია: '||v_reason else 'rejected' end,'resolution_reason',left(v_reason,500),'result','rejected','note',left(v_reason,500),'report_id',v.id,'kind',v.target_kind));
 end if;
 insert into meetany_private.moderation_audit(actor_id,target_type,target_id,action,reason,old_flags,new_flags)
 values(me.id,'report',v.id,'report.resolve',v_reason,jsonb_build_object('status',v.status),jsonb_build_object('action',p_action,'kind',v.target_kind,'target_id',v.target_id,'effect',v_effect));
 insert into meetany_private.business_audit(actor_id,target_id,action,detail)
 values(me.id,v.id,'report_'||case when p_action='hide' then 'hidden' else 'rejected' end,
  jsonb_build_object('kind',v.target_kind,'target_id',v.target_id,'reason',v_reason,'effect',v_effect,'closed',v_closed));
 return jsonb_build_object('id',v.id,'action',p_action,'effect',v_effect,'closed',v_closed);
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_site_content(p_content jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_admin(); k text; val text; origin text:=meetany_private.photo_origin();
begin
 if p_content is null or jsonb_typeof(p_content)<>'object' or octet_length(p_content::text)>20000 then raise exception using errcode='22023',message='invalid content'; end if;
 for k,val in select key,value from jsonb_each_text(p_content) loop
 if k<>all(array['heroTitle','heroAccent','heroSubtitle','companiesTitle','requestsTitle','businessTitle','businessSubtitle','heroLabel1','heroLabel2','heroLabel3','heroLabel4','heroImage1','heroImage2','heroImage3','heroImage4','businessImage1','businessImage2','businessImage3','businessImage4','businessImage5','businessImage6','businessImage7','businessImage8','businessImage9']) or jsonb_typeof(p_content->k)<>'string' or length(val)>1000 then raise exception using errcode='22023',message='invalid content field'; end if;
 if k like '%Image%' and val<>'' and not (val ~ '^/(images|assets/photos)/[A-Za-z0-9_/-]+\.(jpg|jpeg|png|webp|avif)$' or (origin is not null and lower(left(val,length(origin)+1))=origin||'/' and val ~ '^https://[a-z0-9]+\.public\.blob\.vercel-storage\.com/[0-9a-f-]{36}/site-[A-Za-z0-9_-]+\.(jpg|png|webp|gif)$')) then raise exception using errcode='22023',message='invalid content photo'; end if;
 end loop;
 insert into meetany_private.site_content(id,content) values(true,p_content) on conflict(id) do update set content=excluded.content,updated_at=now();
 insert into meetany_private.business_audit(actor_id,target_id,action,detail) values(me.id,me.id,'site_content_saved',jsonb_build_object('keys',array(select jsonb_object_keys(p_content))));
 return p_content;
end $function$

CREATE OR REPLACE FUNCTION public.admin_save_site_design(p_config jsonb, p_version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_admin(); k text; v jsonb; current_version integer;
begin
 if p_config is null or jsonb_typeof(p_config)<>'object' or (select count(*) from jsonb_object_keys(p_config))<>9 then
  raise exception using errcode='22023',message='invalid design settings';
 end if;
 for k,v in select key,value from jsonb_each(p_config) loop
  if not (case k
   when 'primary' then jsonb_typeof(v)='string' and (v#>>'{}')=any(array['#2b66de','#1d4ed8','#0f766e','#7c3aed','#be123c','#171717'])
   when 'controlHeight' then v=any(array['44','48','52']::jsonb[])
   when 'buttonRadius' then v=any(array['4','8','12']::jsonb[])
   when 'fieldRadius' then v=any(array['4','8','12']::jsonb[])
   when 'cardRadius' then v=any(array['8','12','16','20']::jsonb[])
   when 'buttonFont' then v=any(array['14','15','16']::jsonb[])
   when 'bodyFont' then v=any(array['16','17','18']::jsonb[])
   when 'spacing' then v=any(array['100','110','120']::jsonb[])
   when 'badgeStyle' then (v#>>'{}')=any(array['outline','soft']) and jsonb_typeof(v)='string'
   else false end) then raise exception using errcode='22023',message='invalid design setting'; end if;
 end loop;
 -- Serialize saves, including the first one, so two editors cannot overwrite each other.
 perform pg_advisory_xact_lock(20261009,1);
 select version into current_version from meetany_private.site_design where id;
 if p_version is null or p_version<>coalesce(current_version,0) then
  raise exception using errcode='MA409',message='MA409: design settings changed; reload before saving';
 end if;
 insert into meetany_private.site_design(id,config,version) values(true,p_config,coalesce(current_version,0)+1)
 on conflict(id) do update set config=excluded.config,version=excluded.version,updated_at=now();
 insert into meetany_private.business_audit(actor_id,target_id,action,detail)
 values(me.id,me.id,'site_design_saved',jsonb_build_object('version',coalesce(current_version,0)+1));
 return public.site_design();
end $function$

CREATE OR REPLACE FUNCTION public.admin_search_offers(p_q text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_cursor jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 25, p_expired boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  me public.profiles := meetany_private.require_admin();
  v_cursor jsonb := meetany_private.admin_page_cursor(p_cursor);
  v_asof timestamptz := (v_cursor->>'asOf')::timestamptz;
  v_limit integer := least(coalesce(p_limit,25),100);
  v_q text := nullif(btrim(p_q),'');
  v_today date := meetany_private.today();
  result jsonb;
begin
  if v_limit < 1 then raise exception using errcode = '22023', message = 'limit must be positive'; end if;
  if char_length(v_q) > 200 then raise exception using errcode = '22023', message = 'search is too long'; end if;
  if p_status is not null and p_status not in ('sent','chosen','declined','withdrawn') then
    raise exception using errcode = '22023', message = 'invalid offer status'; end if;
  with source as (
    select o.*, coalesce(nullif(p.company,''),p.name) as company_name,
           r.title as request_title, r.hidden as request_hidden, p.name as search_name,
           (o.valid_until is not null and o.valid_until < v_today) as expired,
           (select d.id from meetany_private.deals d where d.offer_id=o.id) as deal_id
    from public.offers o join public.profiles p on p.id=o.company_id
    join public.requests r on r.id=o.request_id
  ), filtered as materialized (
    select * from source x where x.created_at <= v_asof
      and (v_q is null or position(lower(v_q) in lower(concat_ws(' ',x.id::text,x.request_id::text,x.company_id::text,x.body,x.company_name,x.search_name,x.request_title))) > 0)
      and (p_status is null or x.status=p_status)
      and (p_expired is null or x.expired=p_expired)
  ), candidates as (
    select * from filtered x
    where p_cursor is null or (x.created_at,x.id) < ((v_cursor->>'created_at')::timestamptz,(v_cursor->>'id')::uuid)
    order by x.created_at desc,x.id desc limit v_limit+1
  ), page as (select * from candidates order by created_at desc,id desc limit v_limit)
  select jsonb_build_object(
    'items',coalesce((select jsonb_agg(to_jsonb(p) - 'search_name' order by p.created_at desc,p.id desc) from page p),'[]'::jsonb),
    'hasMore',(select count(*)>v_limit from candidates),
    'nextCursor',case when (select count(*)>v_limit from candidates) then
      (select jsonb_build_object('created_at',created_at,'id',id,'asOf',v_asof) from page order by created_at,id limit 1) end,
    'filteredTotal',(select count(*) from filtered),'asOf',v_asof) into result;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.admin_search_requests(p_q text DEFAULT NULL::text, p_state text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_cursor jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  me public.profiles := meetany_private.require_admin();
  v_cursor jsonb := meetany_private.admin_page_cursor(p_cursor);
  v_asof timestamptz := (v_cursor->>'asOf')::timestamptz;
  v_limit integer := least(coalesce(p_limit,25),100);
  v_q text := nullif(btrim(p_q),'');
  result jsonb;
begin
  if v_limit < 1 then raise exception using errcode = '22023', message = 'limit must be positive'; end if;
  if char_length(v_q) > 200 then raise exception using errcode = '22023', message = 'search is too long'; end if;
  if p_state is not null and p_state not in ('open','closed','expired','chosen','hidden') then
    raise exception using errcode = '22023', message = 'invalid request state'; end if;
  if p_category is not null and not meetany_private.is_category(p_category) then
    raise exception using errcode = '22023', message = 'invalid category'; end if;
  with source as (select r.*, case when r.hidden then 'hidden' when r.chosen_offer_id is not null then 'chosen'
              when r.status = 'closed' then 'closed' when r.expires_at <= v_asof then 'expired' else 'open' end as state,
              p.name as owner_name, p.company as owner_company
       from public.requests r join public.profiles p on p.id=r.owner_id),
  filtered as materialized (
    select * from source x where x.created_at <= v_asof and (v_q is null or position(lower(v_q) in lower(x.id::text || ' ' || x.title || ' ' || x.body || ' ' || x.owner_company || ' ' || x.owner_name)) > 0)
       and (p_state is null or x.state=p_state) and (p_category is null or x.category=p_category)
  ), candidates as (
    select * from filtered x
    where p_cursor is null or (x.created_at,x.id) < ((v_cursor->>'created_at')::timestamptz,(v_cursor->>'id')::uuid)
    order by x.created_at desc,x.id desc limit v_limit+1
  ), page as (select * from candidates order by created_at desc,id desc limit v_limit)
  select jsonb_build_object(
    'items',coalesce((select jsonb_agg(to_jsonb(p) || jsonb_build_object('offer_count',(select count(*) from public.offers o where o.request_id=p.id)) order by p.created_at desc,p.id desc) from page p),'[]'::jsonb),
    'hasMore',(select count(*)>v_limit from candidates),
    'nextCursor',case when (select count(*)>v_limit from candidates) then
      (select jsonb_build_object('created_at',created_at,'id',id,'asOf',v_asof) from page order by created_at,id limit 1) end,
    'filteredTotal',(select count(*) from filtered),'asOf',v_asof) into result;
  return result;
end $function$

