CREATE OR REPLACE FUNCTION public.advance_deal(p_deal_id uuid, p_stage text, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_user(); d meetany_private.deals;
begin
 select * into d from meetany_private.deals where id=p_deal_id and me.id in (buyer_id,supplier_id) for update;
 if not found then perform meetany_private.flow_fail('MA901'); end if;
 if p_expected_revision is distinct from d.revision then perform meetany_private.flow_fail('MA904'); end if;
 if p_stage is null or not ((p_stage='discuss' and d.stage='selected') or (p_stage='progress' and d.stage='terms')
 or (p_stage='complete' and d.stage='progress') or (p_stage='cancelled' and d.stage in ('selected','discuss','terms'))) then perform meetany_private.flow_fail('MA903'); end if;
 if p_stage='progress' and (d.buyer_confirmed_at is null or d.supplier_confirmed_at is null) then perform meetany_private.flow_fail('MA905'); end if;
 if p_stage='complete' and me.id<>d.buyer_id then perform meetany_private.flow_fail('MA906'); end if;
 update meetany_private.deals set stage=p_stage,revision=revision+1,
 discuss_at=case when p_stage='discuss' then now() else discuss_at end,
 progress_at=case when p_stage='progress' then now() else progress_at end,
 complete_at=case when p_stage='complete' then now() else complete_at end,
 cancelled_at=case when p_stage='cancelled' then now() else cancelled_at end where id=d.id returning * into d;
 perform meetany_private.deal_event(d,p_stage);return to_jsonb(d);
end $function$

CREATE OR REPLACE FUNCTION public.append_file_chunk(p_upload_id uuid, p_offset integer, p_chunk bytea)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_user(); u meetany_private.file_uploads; n integer;
begin
 select * into u from meetany_private.file_uploads where id=p_upload_id and owner_id=me.id for update;
 if not found or u.created_at<now()-interval '1 day' or u.completed_id is not null or not meetany_private.file_scope(u.kind,u.target_id,true) then perform meetany_private.flow_fail('MA901'); end if;
 n:=octet_length(u.content);
 if p_offset is null or p_offset<0 or p_chunk is null or octet_length(p_chunk) not between 1 and 1048576 or p_offset+octet_length(p_chunk)>u.expected_size then perform meetany_private.flow_fail('MA902'); end if;
 if p_offset<n and substring(u.content from p_offset+1 for octet_length(p_chunk))=p_chunk then return n; end if;
 if p_offset<>n then perform meetany_private.flow_fail('MA904'); end if;
 update meetany_private.file_uploads set content=content||p_chunk where id=u.id;
 return n+octet_length(p_chunk);
end $function$

