end $function$

CREATE OR REPLACE FUNCTION public.begin_file_upload(p_kind text, p_target uuid, p_name text, p_mime text, p_size integer, p_slot text DEFAULT ''::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_user(); result uuid;
begin
 if not meetany_private.file_scope(p_kind,p_target,true) then perform meetany_private.flow_fail('MA901'); end if;
 if p_size is null or p_size not between 1 and 10485760 or p_mime not in ('application/pdf','image/jpeg','image/png','image/webp') or length(coalesce(p_name,'')) not between 1 and 180 or p_name~'[[:cntrl:]]' or length(coalesce(p_slot,''))>80 then perform meetany_private.flow_fail('MA902'); end if;
 perform pg_advisory_xact_lock(hashtextextended(me.id::text,0));
 delete from meetany_private.file_uploads where owner_id=me.id and created_at<now()-interval '1 day';
 if (select count(*) from meetany_private.file_uploads where owner_id=me.id and completed_id is null)>=10
 or (select count(*) from meetany_private.attachments where kind=p_kind and target_id=p_target)>=10
 or (select coalesce(sum(octet_length(content)),0) from meetany_private.attachments where owner_id=me.id)>524288000 then perform meetany_private.flow_fail('MA902'); end if;
 insert into meetany_private.file_uploads(owner_id,kind,target_id,slot,name,mime,expected_size) values(me.id,p_kind,p_target,coalesce(p_slot,''),p_name,p_mime,p_size) returning id into result;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.bind_draft_files(p_kind text, p_draft uuid, p_target uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_user();
begin
 if p_kind not in('request','offer') or not meetany_private.file_scope(p_kind,p_target,true) then perform meetany_private.flow_fail('MA901'); end if;
 perform pg_advisory_xact_lock(hashtextextended(p_kind||p_target::text,0));
 if (select count(*) from meetany_private.attachments where (kind=p_kind and target_id=p_target) or (owner_id=me.id and kind=p_kind||'_draft' and target_id=p_draft))>10 then perform meetany_private.flow_fail('MA902'); end if;
 update meetany_private.attachments set kind=p_kind,target_id=p_target where owner_id=me.id and kind=p_kind||'_draft' and target_id=p_draft;
end $function$

CREATE OR REPLACE FUNCTION public.choose_offer(p_offer_id uuid, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS offers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  me public.profiles := meetany_private.require_user();
  o public.offers;
  r public.requests;
begin
  select * into o from public.offers where id = p_offer_id;
  if not found then perform meetany_private.fail('MA206'); end if;
  select * into r from public.requests where id = o.request_id for update;  -- serializes choices and edits
  if r.owner_id <> me.id then
    if o.company_id = me.id or me.role = 'admin' then perform meetany_private.fail('MA107'); end if;
    perform meetany_private.fail('MA206');  -- a sealed offer the caller cannot see
  end if;
  if meetany_private.request_state(r) <> 'open' then perform meetany_private.fail('MA208'); end if;
  select * into o from public.offers where id = p_offer_id for update;  -- current version, after the lock
  if not found then perform meetany_private.fail('MA206'); end if;
  if p_expected_updated_at is not null and o.updated_at <> p_expected_updated_at then
    perform meetany_private.fail('MA209');
  end if;
  update public.offers
     set status = case when id = o.id then 'chosen' else 'declined' end
   where request_id = r.id;
  update public.requests set chosen_offer_id = o.id where id = r.id;
  select * into o from public.offers where id = p_offer_id;
  return o;
end
$function$

CREATE OR REPLACE FUNCTION public.company_reviews(p_company_id uuid, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
 if not meetany_private.can_view_company(p_company_id) then perform meetany_private.fail('MA302'); end if;
 if p_offset is null or p_offset<0 then raise exception using errcode='22023',message='invalid offset'; end if;
 if not exists(select 1 from public.profiles where id=p_company_id and role='company' and not blocked) then perform meetany_private.fail('MA302'); end if;
 select jsonb_build_object('total',count(*),'rating',round(avg(v.rating),1)) into result
 from meetany_private.company_reviews v join public.profiles a on a.id=v.author_id and not a.blocked
 where v.company_id=p_company_id and v.status='published';
 return result || jsonb_build_object('items',(select coalesce(jsonb_agg(to_jsonb(t)),'[]') from (
 select v.id,v.author_id,v.rating,v.body,v.updated_at,coalesce(nullif(a.company,''),a.name) author
 from meetany_private.company_reviews v join public.profiles a on a.id=v.author_id and not a.blocked
 where v.company_id=p_company_id and v.status='published' order by v.updated_at desc,v.id limit 10 offset p_offset) t));
end $function$

