CREATE OR REPLACE FUNCTION public.complete_profile(p_role text, p_name text, p_company text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_industry text DEFAULT NULL::text)
 RETURNS profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := meetany_private.uid();
  u record;
  p public.profiles;
  v_role text := case when p_role = 'company' then 'company' else 'client' end;  -- never admin
  v_name text := left(btrim(coalesce(p_name, '')), 80);
  v_company text := left(btrim(coalesce(p_company, '')), 100);
  v_email text;
  v_phone text := meetany_private.normalize_phone(p_phone);
  v_industry text := nullif(p_industry, '');
begin
  if v_uid is null then perform meetany_private.fail('MA001'); end if;
  select nu.email, nu."emailVerified" as verified into u from neon_auth."user" nu where nu.id = v_uid;
  if not found then perform meetany_private.fail('MA001'); end if;
  select * into p from public.profiles where id = v_uid;
  if found then return p; end if;
  -- Email verification is on unless meetany_private.settings has require_email_verification = 'off'.
  if u.verified is not true
     and coalesce((select value from meetany_private.settings where key = 'require_email_verification'), 'on') <> 'off'
  then perform meetany_private.fail('MA408'); end if;
  v_email := lower(btrim(coalesce(u.email, '')));
  if char_length(v_name) < 2 then perform meetany_private.fail('MA401'); end if;
  if v_role = 'company' and char_length(v_company) < 2 then perform meetany_private.fail('MA402'); end if;
  if v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then perform meetany_private.fail('MA403'); end if;
  if v_phone is null then perform meetany_private.fail('MA404'); end if;
  if not meetany_private.is_city(p_city) then perform meetany_private.fail('MA104'); end if;
  if v_role = 'company' and not meetany_private.is_category(v_industry) then perform meetany_private.fail('MA407'); end if;
  if exists (select 1 from public.profiles x where x.phone = v_phone) then perform meetany_private.fail('MA405'); end if;
  begin
    insert into public.profiles (id, role, name, company, phone, email, city, industry)
    values (v_uid, v_role, v_name, case when char_length(v_company) >= 2 then v_company else v_name end,
            v_phone, v_email, p_city, case when v_role = 'company' then v_industry end)
    on conflict (id) do nothing;
  exception when unique_violation then
    perform meetany_private.fail('MA405');  -- concurrent sign-up took the same number
  end;
  select * into p from public.profiles where id = v_uid;
  return p;
end
$function$

CREATE OR REPLACE FUNCTION public.confirm_deal_terms(p_deal_id uuid, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_user(); d meetany_private.deals;
begin
 select * into d from meetany_private.deals where id=p_deal_id and me.id in (buyer_id,supplier_id) for update;
 if not found then perform meetany_private.flow_fail('MA901'); end if;
 if p_expected_revision is distinct from d.revision then perform meetany_private.flow_fail('MA904'); end if;
 if d.stage<>'terms' or d.total_price is null then perform meetany_private.flow_fail('MA903'); end if;
 if (me.id=d.buyer_id and d.buyer_confirmed_at is not null) or (me.id=d.supplier_id and d.supplier_confirmed_at is not null) then return to_jsonb(d); end if;
 update meetany_private.deals set revision=revision+1,
 buyer_confirmed_at=case when me.id=buyer_id then now() else buyer_confirmed_at end,
 supplier_confirmed_at=case when me.id=supplier_id then now() else supplier_confirmed_at end where id=d.id returning * into d;
 perform meetany_private.deal_event(d,'confirm_terms');return to_jsonb(d);
end $function$

CREATE OR REPLACE FUNCTION public.contact_for_request(p_request_id uuid)
 RETURNS TABLE(name text, company text, phone text, email text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me uuid:=meetany_private.uid(); r public.requests; o public.offers; other uuid;
begin
 if me is null or not meetany_private.can_write() then return; end if;
 select * into r from public.requests where id=p_request_id;
 if r.id is null or r.chosen_offer_id is null then return; end if;
 if exists(select 1 from meetany_private.deals where request_id=r.id and stage='cancelled') then return; end if;
 select * into o from public.offers where id=r.chosen_offer_id;
 if me=r.owner_id then other:=o.company_id; elsif me=o.company_id then other:=r.owner_id; else return; end if;
 return query select p.name,p.company,p.phone,p.email from public.profiles p where p.id=other and not p.blocked;
end $function$

CREATE OR REPLACE FUNCTION public.count_matching_suppliers(p_category text, p_city text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n integer;
begin
 -- p_city is accepted for symmetry with list_matching, which only uses the city for ranking.
 if not coalesce(meetany_private.is_category(p_category),false) then perform meetany_private.flow_fail('MA902'); end if;
 select count(*)::integer into n from meetany_private.matching_suppliers(p_category,meetany_private.uid()) m where m.alerted;
 return n;
end $function$

CREATE OR REPLACE FUNCTION public.create_request(p_title text, p_body text, p_category text, p_city text, p_photo_url text DEFAULT NULL::text, p_quantity numeric DEFAULT NULL::numeric, p_unit text DEFAULT NULL::text, p_needed_by date DEFAULT NULL::date, p_address_note text DEFAULT NULL::text)
 RETURNS requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  me public.profiles := meetany_private.require_user();
  v_title text := rtrim(left(btrim(coalesce(p_title, '')), 120));
  v_body text := rtrim(left(btrim(coalesce(p_body, '')), 2000));
  v_photo text := nullif(btrim(coalesce(p_photo_url, '')), '');
  v_origin text := meetany_private.photo_origin();
  v_address_note text := nullif(btrim(p_address_note), '');
  v_terms record;
  r public.requests;
begin
  perform 1 from public.profiles where id = me.id for update;  -- serialize per owner
  if meetany_private.open_count(me.id) >= 5 then perform meetany_private.fail('MA105'); end if;
  if char_length(v_title) < 1 then perform meetany_private.fail('MA101'); end if;
  if char_length(v_body) < 10 then perform meetany_private.fail('MA102'); end if;
  if not meetany_private.is_category(p_category) then perform meetany_private.fail('MA103'); end if;
  if not meetany_private.is_city(p_city) then perform meetany_private.fail('MA104'); end if;
  -- Photo: <Blob store origin>/<caller id>/<file>. Only /api/blob-upload can mint an upload
  -- token for '<uid>/…', and only for a caller whose verified JWT has sub = uid.
  if v_photo is not null and (
       v_origin is null
       or not meetany_private.valid_photo_url(v_photo, me.id)
       or lower(left(v_photo, char_length(v_origin) + 1)) <> v_origin || '/'
       or substr(v_photo, char_length(v_origin) + 2, 37) <> me.id::text || '/') then
    perform meetany_private.fail('MA109');
  end if;
  if char_length(v_address_note) > 120 then perform meetany_private.fail('MA114'); end if;
  v_terms := meetany_private.check_terms(p_quantity, p_unit, p_needed_by);
  insert into public.requests (owner_id, title, body, category, city, photo_url, quantity, unit, needed_by, address_note)
  values (me.id, v_title, v_body, p_category, p_city, v_photo, v_terms.quantity, v_terms.unit, p_needed_by, v_address_note)
  returning * into r;
  return r;
end
$function$

CREATE OR REPLACE FUNCTION public.create_request_full(p_title text, p_body text, p_category text, p_city text, p_photo_url text, p_quantity numeric, p_unit text, p_needed_by date, p_address_note text, p_preferences jsonb, p_draft uuid)
 RETURNS requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.requests;
begin
 r:=public.create_request(p_title,p_body,p_category,p_city,p_photo_url,p_quantity,p_unit,p_needed_by,p_address_note);
 perform public.set_request_preferences(r.id,p_preferences);
 if p_draft is not null then perform public.bind_draft_files('request',p_draft,r.id); end if;
 return r;
end $function$

