CREATE OR REPLACE FUNCTION public.list_matching_feed(p_kind text DEFAULT 'recommended'::text, p_city text DEFAULT NULL::text, p_limit integer DEFAULT 12, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_user(); result jsonb;
begin
 if me.role not in('company','client') then perform meetany_private.flow_fail('MA901'); end if;
 if p_kind not in('recommended','requests','suppliers') or p_limit not between 1 and 100 or p_offset not between 0 and 10000 or (p_city is not null and not meetany_private.is_city(p_city)) then perform meetany_private.flow_fail('MA902'); end if;
 with matches as (
 select r.id,'request'::text kind,r.title,p.company,r.category,r.city,p.industry,p.verified,r.created_at,70+case when r.city=me.city or r.city=any(me.service_cities) then 30 else 0 end score from public.requests r join public.profiles p on p.id=r.owner_id
 where me.role='company' and p_kind in('recommended','requests') and r.owner_id<>me.id and not r.hidden and not p.blocked and meetany_private.request_state(r)='open' and r.category=any(me.provide_categories) and (p_city is null or r.city=p_city)
 union all
 select p.id,'supplier',p.company,p.company,p.industry,p.city,p.industry,p.verified,p.created_at,70+case when p.city=me.city or me.city=any(p.service_cities) then 30 else 0 end from public.profiles p
 where p_kind in('recommended','suppliers') and p.role='company' and p.verified and not p.blocked and not p.catalog_hidden and p.id<>me.id and (p.industry=any(me.need_categories) or p.provide_categories&&me.need_categories or exists(select 1 from public.requests r where r.owner_id=me.id and not r.hidden and meetany_private.request_state(r)='open' and (r.category=p.industry or r.category=any(p.provide_categories)))) and (p_city is null or p.city=p_city or p_city=any(p.service_cities))
 ) select coalesce(jsonb_agg(to_jsonb(x) order by score desc,created_at desc,id),'[]') into result from (select * from matches order by score desc,created_at desc,id limit p_limit offset p_offset) x;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.list_messages(p_conversation_id uuid, p_after timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_user(); result jsonb;
begin
 perform meetany_private.require_conversation(p_conversation_id,me.id);
 if p_after is not null and not isfinite(p_after) then raise exception using errcode='22023',message='invalid message timestamp'; end if;
 select coalesce(jsonb_agg(to_jsonb(m) order by created_at,id),'[]'::jsonb) into result
 from meetany_private.messages m where conversation_id=p_conversation_id and (p_after is null or created_at>p_after);
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.log_contact_event(p_target_kind text, p_target_id uuid, p_kind text, p_source text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles; actor uuid:=meetany_private.uid(); at_time timestamptz; event_id uuid;
begin
 me:=meetany_private.require_user();
 if p_target_kind is null or p_target_kind not in ('company','request') or p_target_id is null
 or p_kind is null or p_kind not in ('reveal','call') or p_source is null
 or (p_target_kind='company' and p_source not in ('company-list','company-profile','company-partnership'))
 or (p_target_kind='request' and p_source not in ('request-owner','chosen-offer')) then
  raise exception using errcode='22023',message='invalid contact event';
 end if;
 if p_target_kind='company' then
  if not exists(select 1 from public.profiles where id=p_target_id and role='company' and not blocked) then
   raise exception using errcode='22023',message='contact target unavailable'; end if;
 else
  if not exists(select 1 from public.requests r join public.profiles p on p.id=r.owner_id where r.id=p_target_id and not r.hidden and not p.blocked) then
   raise exception using errcode='22023',message='contact target unavailable'; end if;
 end if;
 -- Logging is not contact authorization. The same selected-partner boundary is enforced here.
 if me.role<>'admin' and not exists(
  select 1 from public.requests r join public.offers o on o.id=r.chosen_offer_id
  where ((p_target_kind='company' and o.company_id=p_target_id and r.owner_id=me.id)
    or (p_target_kind='request' and r.id=p_target_id and me.id in (r.owner_id,o.company_id)))
  and not exists(select 1 from meetany_private.deals d where d.request_id=r.id and d.stage='cancelled')
  and not exists(select 1 from public.profiles p where p.id in (r.owner_id,o.company_id) and p.blocked)
 ) then perform meetany_private.flow_fail('MA901'); end if;
 -- Serialize the anonymous global cap, and each signed-in actor's writes.
 perform pg_advisory_xact_lock(hashtextextended('meetany-contact:'||coalesce(actor::text,'anonymous'),0));
 at_time:=clock_timestamp();
 if exists(select 1 from meetany_private.contact_events where actor_id is not distinct from actor
  and target_kind=p_target_kind and target_id=p_target_id and kind=p_kind and created_at>at_time-interval '1 minute')
 or (actor is null and (select count(*) from meetany_private.contact_events where actor_id is null and created_at>at_time-interval '1 minute')>=120) then
  return jsonb_build_object('recorded',false);
 end if;
 insert into meetany_private.contact_events(actor_id,actor_role,target_kind,target_id,kind,source,created_at)
 values(actor,coalesce(me.role,'anonymous'),p_target_kind,p_target_id,p_kind,p_source,at_time) returning id into event_id;
 return jsonb_build_object('recorded',true,'id',event_id);
end $function$

CREATE OR REPLACE FUNCTION public.mark_read(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_user(); c meetany_private.conversations; at_time timestamptz; marked integer;
begin
 c:=meetany_private.require_conversation(p_conversation_id,me.id);
 select * into c from meetany_private.conversations where id=c.id for update;
 if not found then perform meetany_private.fail('MA501'); end if;
 at_time:=clock_timestamp();
 update meetany_private.messages set read_at=at_time where conversation_id=c.id and sender_id<>me.id and read_at is null;
 get diagnostics marked=row_count;
 update meetany_private.conversations set
 client_last_read_at=case when client_id=me.id then at_time else client_last_read_at end,
 company_last_read_at=case when company_id=me.id then at_time else company_last_read_at end where id=c.id;
 return jsonb_build_object('marked',marked,'read_at',at_time);
end $function$

