CREATE OR REPLACE FUNCTION public.open_deal_issue(p_deal_id uuid, p_expected_revision integer, p_reason text, p_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_user(); d meetany_private.deals; i meetany_private.deal_issues;
begin
 select * into d from meetany_private.deals where id=p_deal_id and me.id in(buyer_id,supplier_id) for update;
 if not found then perform meetany_private.flow_fail('MA901'); end if;
 if p_expected_revision is distinct from d.revision then perform meetany_private.flow_fail('MA904'); end if;
 if d.stage not in('progress','complete') or exists(select 1 from meetany_private.deal_issues where deal_id=d.id and status='open') then perform meetany_private.flow_fail('MA903'); end if;
 if p_reason not in('quality','quantity','late','other') or length(btrim(coalesce(p_body,''))) not between 3 and 2000 then perform meetany_private.flow_fail('MA902'); end if;
 insert into meetany_private.deal_issues(deal_id,actor_id,reason,body) values(d.id,me.id,p_reason,btrim(p_body)) returning * into i;
 update meetany_private.deals set revision=revision+1 where id=d.id returning * into d;
 perform meetany_private.deal_event(d,'issue_opened'); return to_jsonb(i);
end $function$

CREATE OR REPLACE FUNCTION public.propose_deal_terms(p_deal_id uuid, p_expected_revision integer, p_total_price numeric, p_quantity numeric, p_unit text, p_delivery_days integer, p_delivery_date date, p_delivery_place text, p_payment_terms text, p_includes text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_user(); d meetany_private.deals;
begin
 select * into d from meetany_private.deals where id=p_deal_id and me.id in (buyer_id,supplier_id) for update;
 if not found then perform meetany_private.flow_fail('MA901'); end if;
 if p_expected_revision is distinct from d.revision then perform meetany_private.flow_fail('MA904'); end if;
 if d.stage not in ('discuss','terms') then perform meetany_private.flow_fail('MA903'); end if;
 if p_total_price is null or p_total_price not between 0.01 and 1000000000
 or p_quantity is null or p_quantity not between 0.001 and 1000000000
 or not coalesce(meetany_private.is_unit(p_unit),false)
 or p_delivery_days is null or p_delivery_days not between 0 and 365
 or (p_delivery_date is not null and (not isfinite(p_delivery_date) or p_delivery_date<meetany_private.today()))
 or length(btrim(coalesce(p_delivery_place,''))) not between 1 and 500
 or length(btrim(coalesce(p_payment_terms,''))) not between 1 and 500
 or p_includes is null or not meetany_private.valid_items(p_includes) then perform meetany_private.flow_fail('MA902'); end if;
 update meetany_private.deals set stage='terms',terms_at=coalesce(terms_at,now()),revision=revision+1,
 total_price=p_total_price,quantity=p_quantity,unit=p_unit,delivery_days=p_delivery_days,delivery_date=p_delivery_date,
 delivery_place=btrim(p_delivery_place),payment_terms=btrim(p_payment_terms),includes=p_includes,
 buyer_confirmed_at=null,supplier_confirmed_at=null where id=d.id returning * into d;
 perform meetany_private.deal_event(d,'propose_terms');return to_jsonb(d);
end $function$

CREATE OR REPLACE FUNCTION public.rate_deal(p_deal_id uuid, p_rating integer, p_review text, p_expected_revision integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_user(); d meetany_private.deals; v meetany_private.company_reviews;
begin
 select * into d from meetany_private.deals where id=p_deal_id and buyer_id=me.id for update;
 if not found then perform meetany_private.flow_fail('MA901'); end if;
 if p_expected_revision is distinct from d.revision then perform meetany_private.flow_fail('MA904'); end if;
 if d.stage<>'complete' or d.rating is not null then perform meetany_private.flow_fail('MA903'); end if;
 if p_rating is null or p_rating not between 1 and 5 or length(coalesce(p_review,''))>2000 then perform meetany_private.flow_fail('MA902'); end if;
 update meetany_private.deals set rating=p_rating,review=btrim(p_review),rated_at=now(),revision=revision+1 where id=d.id returning * into d;
 perform meetany_private.deal_event(d,'rated');
 -- Publish on the company profile; a review the moderators hid (or one written by someone else) is left alone.
 insert into meetany_private.company_reviews(request_id,author_id,company_id,rating,body,status)
 values(d.request_id,d.buyer_id,d.supplier_id,p_rating,left(btrim(coalesce(p_review,'')),1500),'published')
 on conflict(request_id) do update set company_id=excluded.company_id,rating=excluded.rating,body=excluded.body,status=case when company_reviews.status='hidden' then 'hidden' else 'published' end,updated_at=now() where company_reviews.author_id=d.buyer_id returning * into v;
 if v.id is not null then
  insert into meetany_private.business_audit(actor_id,target_id,action,detail) values(me.id,v.id,'review_saved',jsonb_build_object('rating',v.rating,'status',v.status,'source','deal'));
 end if;
 return to_jsonb(d);
end $function$

CREATE OR REPLACE FUNCTION public.rate_deal_full(p_deal_id uuid, p_expected_revision integer, p_scores integer[], p_would_again boolean, p_review text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d jsonb; average_rating integer;
begin
 if cardinality(p_scores) is distinct from 4 or array_position(p_scores,null) is not null or exists(select 1 from unnest(p_scores) n where n not between 1 and 5) or p_would_again is null then perform meetany_private.flow_fail('MA902'); end if;
 select round(avg(v))::integer into average_rating from unnest(p_scores) v;
 d:=public.rate_deal(p_deal_id,average_rating,p_review,p_expected_revision);
 insert into meetany_private.deal_reviews(deal_id,scores,would_again) values(p_deal_id,p_scores,p_would_again);
 return d;
end $function$

CREATE OR REPLACE FUNCTION public.record_registration_event(p_event_id uuid, p_session_id uuid, p_role text, p_stage text, p_source text DEFAULT 'unknown'::text, p_device text DEFAULT 'unknown'::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare session_row meetany_private.registration_sessions; profile_row public.profiles; affected integer;
begin
 if p_event_id is null or p_session_id is null or p_role is null or p_role not in ('client','company')
 or p_stage is null or p_stage not in ('form_open','form_started','form_submitted','email_pending','profile_created')
 or p_source is null or p_source not in('direct','header','request','company','account','unknown')
 or p_device is null or p_device not in('mobile','tablet','desktop','unknown') then
  raise exception using errcode='MA801',message='invalid registration event';
 end if;
 -- Persistent global ceiling limits growth even if a visitor rotates their attempt UUID.
 -- It intentionally stores no network identity; guest telemetry is never billing or audit evidence.
 perform pg_advisory_xact_lock(hashtext('registration_daily_limit'));
 if exists(select 1 from meetany_private.registration_events where id=p_event_id) then return false; end if;
 if (select count(*) from meetany_private.registration_events where created_at>=date_trunc('day',now()))>=20000 then
  raise exception using errcode='MA802',message='registration telemetry daily limit';
 end if;
 if p_stage='form_open' then
  -- Keep only the most recent 90 days of this anonymous funnel, including linked completion IDs.
  delete from meetany_private.registration_sessions where created_at<now()-interval '90 days';
  insert into meetany_private.registration_sessions(id,role,source,device) values(p_session_id,p_role,p_source,p_device) on conflict(id) do nothing;
 end if;
 select * into session_row from meetany_private.registration_sessions where id=p_session_id for update;
 if not found or session_row.role<>p_role or session_row.created_at<now()-interval '24 hours' then
  raise exception using errcode='MA801',message='registration attempt missing or expired';
 end if;
 if p_stage='profile_created' then
  profile_row:=meetany_private.require_user();
  if profile_row.role<>p_role or profile_row.created_at<session_row.created_at-interval '1 minute' then
   raise exception using errcode='MA803',message='registration completion not confirmed';
  end if;
 end if;
 insert into meetany_private.registration_events(id,session_id,stage,profile_id)
 values(p_event_id,p_session_id,p_stage,case when p_stage='profile_created' then profile_row.id end)
 on conflict do nothing;
 get diagnostics affected=row_count;
 if affected>0 then update meetany_private.registration_sessions set last_event_at=now() where id=p_session_id; end if;
 return affected>0;
end $function$

