CREATE OR REPLACE FUNCTION public.save_company_review(p_request_id uuid, p_rating integer, p_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_user(); company uuid; v meetany_private.company_reviews;
begin
 if p_rating is null or p_rating not between 1 and 5 or p_body is null or length(btrim(p_body)) not between 20 and 1500 then raise exception using errcode='22023',message='MA601: invalid review'; end if;
 select d.supplier_id into company from public.requests r
 join meetany_private.deals d on d.request_id=r.id and d.stage='complete' and d.buyer_id=me.id
 join public.profiles c on c.id=d.supplier_id and not c.blocked and c.role='company'
 where r.id=p_request_id and r.owner_id=me.id and not r.hidden and d.supplier_id<>me.id for share of r;
 if company is null then raise exception using errcode='42501',message='MA602: review requires a completed deal'; end if;
 insert into meetany_private.company_reviews(request_id,author_id,company_id,rating,body,status) values(p_request_id,me.id,company,p_rating,btrim(p_body),'published')
 on conflict(request_id) do update set company_id=excluded.company_id,rating=excluded.rating,body=excluded.body,status=case when company_reviews.status='hidden' then 'hidden' else 'published' end,updated_at=now() where company_reviews.author_id=me.id returning * into v;
 if v.id is null then raise exception using errcode='42501',message='MA602: review is not yours'; end if;
 insert into meetany_private.business_audit(actor_id,target_id,action,detail) values(me.id,v.id,'review_saved',jsonb_build_object('rating',v.rating,'status',v.status));
 return to_jsonb(v);
end $function$

CREATE OR REPLACE FUNCTION public.select_offer_deal(p_offer_id uuid, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_user(); o public.offers; r public.requests; d meetany_private.deals;
begin
 select * into o from public.offers where id=p_offer_id;
 select * into r from public.requests where id=o.request_id for update;
 if r.id is null or r.owner_id<>me.id then perform meetany_private.flow_fail('MA901'); end if;
 select * into d from meetany_private.deals where request_id=r.id;
 if found then
  if d.offer_id<>p_offer_id or d.stage='cancelled' then perform meetany_private.flow_fail('MA903'); end if;
  return to_jsonb(d);
 end if;
 select * into o from public.offers where id=p_offer_id for update;
 if p_expected_updated_at is not null and o.updated_at<>p_expected_updated_at then perform meetany_private.flow_fail('MA904'); end if;
 if exists(select 1 from public.profiles where id=o.company_id and blocked) then perform meetany_private.flow_fail('MA901'); end if;
 if r.chosen_offer_id is null then
  if o.valid_until<meetany_private.today() then perform meetany_private.flow_fail('MA903'); end if;
  perform public.choose_offer(p_offer_id,p_expected_updated_at);
 elsif r.chosen_offer_id<>p_offer_id then perform meetany_private.flow_fail('MA903'); end if;
 insert into meetany_private.deals(request_id,offer_id,buyer_id,supplier_id,quantity,unit,delivery_days,payment_terms,includes)
 values(r.id,o.id,me.id,o.company_id,r.quantity,r.unit,o.delivery_days,o.payment_terms,o.commercial_terms) returning * into d;
 perform meetany_private.deal_event(d,'selected');
 return to_jsonb(d);
end $function$

CREATE OR REPLACE FUNCTION public.send_message(p_conversation_id uuid, p_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_user(); c meetany_private.conversations;
 text_body text:=regexp_replace(p_body,'^[[:space:]]+|[[:space:]]+$','','g'); at_time timestamptz; m meetany_private.messages;
begin
 c:=meetany_private.require_conversation(p_conversation_id,me.id);
 if text_body is null or char_length(text_body) not between 1 and 2000 then perform meetany_private.fail('MA505'); end if;
 -- Sender lock protects the global sliding-minute cap across all conversations.
 perform pg_advisory_xact_lock(hashtextextended('meetany-message:'||me.id::text,0));
 -- Sending and marking read serialize per conversation; timestamps follow commit order.
 select * into c from meetany_private.conversations where id=c.id for update;
 if not found then perform meetany_private.fail('MA501'); end if;
 at_time:=clock_timestamp();
 if (select count(*) from meetany_private.messages where sender_id=me.id and created_at>at_time-interval '1 minute')>=20
 or exists(select 1 from meetany_private.messages where sender_id=me.id and conversation_id=c.id and created_at>at_time-interval '2 seconds') then
  perform meetany_private.fail('MA506'); end if;
 at_time:=greatest(at_time,c.last_message_at+interval '1 microsecond');
 insert into meetany_private.messages(conversation_id,sender_id,body,created_at)
 values(c.id,me.id,text_body,at_time) returning * into m;
 update meetany_private.conversations set last_message_at=at_time where id=c.id;
 return to_jsonb(m);
end $function$

CREATE OR REPLACE FUNCTION public.send_offer(p_request_id uuid, p_body text, p_price numeric DEFAULT NULL::numeric, p_price_type text DEFAULT NULL::text, p_vat_included boolean DEFAULT NULL::boolean, p_delivery_days integer DEFAULT NULL::integer, p_delivery_included boolean DEFAULT NULL::boolean)
 RETURNS offers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  me public.profiles := meetany_private.require_user();
  r public.requests;
  v_body text := rtrim(left(btrim(coalesce(p_body, '')), 2000));
  v_price numeric(12, 2);
  v_type text := coalesce(p_price_type, case when p_price is null then 'negotiable' else 'total' end);
  o public.offers;
begin
  select * into r from public.requests where id = p_request_id for share;
  if not found or (r.hidden and r.owner_id <> me.id and me.role <> 'admin') then
    perform meetany_private.fail('MA106');
  end if;
  if me.role <> 'company' then perform meetany_private.fail('MA201'); end if;
  if not me.verified then raise exception using errcode='42501',message='MA801: კომპანია ადმინისტრატორის დადასტურებას ელოდება',hint='MA801'; end if;
  if r.owner_id = me.id then perform meetany_private.fail('MA202'); end if;
  if meetany_private.request_state(r) <> 'open' then perform meetany_private.fail('MA203'); end if;
  if char_length(v_body) < 10 then perform meetany_private.fail('MA204'); end if;
  if v_type not in ('unit', 'total', 'negotiable') then perform meetany_private.fail('MA210'); end if;
  if v_type = 'negotiable' and p_price is not null then perform meetany_private.fail('MA211'); end if;
  if v_type <> 'negotiable' and p_price is null then perform meetany_private.fail('MA212'); end if;
  if p_price is not null then
    if p_price = 'NaN'::numeric or p_price <= 0 or p_price > 1000000000 then perform meetany_private.fail('MA205'); end if;
    v_price := round(p_price, 2);
    if v_price <= 0 then perform meetany_private.fail('MA205'); end if;
  end if;
  if p_delivery_days is not null and p_delivery_days not between 0 and 365 then perform meetany_private.fail('MA213'); end if;
  insert into public.offers as x (request_id, company_id, body, price, price_type, vat_included,
                                  delivery_days, delivery_included)
  values (r.id, me.id, v_body, v_price, v_type,
          v_type <> 'negotiable' and coalesce(p_vat_included, false),
          p_delivery_days, coalesce(p_delivery_included, false))
  on conflict (request_id, company_id)
  do update set body = excluded.body, price = excluded.price, price_type = excluded.price_type,
                vat_included = excluded.vat_included, delivery_days = excluded.delivery_days,
                delivery_included = excluded.delivery_included, updated_at = now()
  returning * into o;
  return o;
end
$function$

