CREATE OR REPLACE FUNCTION public.set_my_distribution(p_categories text[], p_channels text[], p_brands text[], p_warehouse text, p_transport text, p_cold_chain boolean, p_min_order text, p_exclusive boolean, p_regions text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_user(); v text; regions text[]:=coalesce(p_regions,me.service_cities);
begin
 if me.role<>'company' then perform meetany_private.fail('MA201'); end if;
 if coalesce(cardinality(regions),0)<1 or cardinality(regions)>40 then perform meetany_private.fail('MA621'); end if;
 foreach v in array regions loop if v is null or not meetany_private.is_city(v) then perform meetany_private.fail('MA621'); end if; end loop;
 if p_categories is null or cardinality(p_categories)>6 or p_channels is null or cardinality(p_channels) not between 1 and 8
  or array_position(p_channels,null) is not null or not (p_channels <@ array['horeca','retail_chain','retail_small','pharmacy','subdistributors','online','institutions','export'])
  then perform meetany_private.fail('MA621'); end if;
 foreach v in array p_categories loop if v is null or not meetany_private.is_category(v) then perform meetany_private.fail('MA621'); end if; end loop;
 if p_brands is null or cardinality(p_brands)>20 then perform meetany_private.fail('MA621'); end if;
 foreach v in array p_brands loop if v is null or length(trim(v)) not between 1 and 80 then perform meetany_private.fail('MA621'); end if; end loop;
 if p_warehouse is null or p_warehouse not in ('none','own','rented') or p_transport is null or p_transport not in ('none','own','contracted')
  or p_cold_chain is null or p_exclusive is null or p_min_order is null or length(trim(p_min_order))>80 then perform meetany_private.fail('MA621'); end if;
 update public.profiles set service_cities=regions where id=me.id;
 insert into meetany_private.company_business(company_id,distributor,dist_categories,dist_channels,dist_brands,dist_warehouse,dist_transport,dist_cold_chain,dist_min_order,dist_exclusive)
 values(me.id,true,p_categories,p_channels,p_brands,p_warehouse,p_transport,p_cold_chain,trim(p_min_order),p_exclusive)
 on conflict(company_id) do update set distributor=true,dist_categories=excluded.dist_categories,dist_channels=excluded.dist_channels,dist_brands=excluded.dist_brands,
 dist_warehouse=excluded.dist_warehouse,dist_transport=excluded.dist_transport,dist_cold_chain=excluded.dist_cold_chain,dist_min_order=excluded.dist_min_order,dist_exclusive=excluded.dist_exclusive,updated_at=now();
 return public.my_business_settings();
end $function$

CREATE OR REPLACE FUNCTION public.set_my_gallery(p_urls text[])
 RETURNS profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  me public.profiles := meetany_private.require_user();
  v_origin text := meetany_private.photo_origin();
  v_urls text[] := array(select u from (select btrim(x) u, min(n) n from unnest(coalesce(p_urls, '{}'::text[])) with ordinality a(x, n)
                                       where btrim(coalesce(x, '')) <> '' group by 1) d order by n);
  p public.profiles;
begin
  if me.role <> 'company' then perform meetany_private.fail('MA116'); end if;
  if cardinality(v_urls) > 8 or (cardinality(v_urls) > 0 and v_origin is null) or exists (
       select 1 from unnest(v_urls) u
       where not meetany_private.valid_photo_url(u, me.id)
          or lower(left(u, char_length(v_origin) + 1)) <> v_origin || '/'
          or substr(u, char_length(v_origin) + 2, 45) <> me.id::text || '/gallery-') then
    perform meetany_private.fail('MA116');
  end if;
  update public.profiles set gallery = v_urls where id = me.id returning * into p;
  return p;
end
$function$

CREATE OR REPLACE FUNCTION public.set_my_products(p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_user(); item jsonb; cleaned jsonb:='[]'; product jsonb;
begin
 if me.role<>'company' then perform meetany_private.fail('MA201'); end if;
 if p_items is null or jsonb_typeof(p_items)<>'array' then perform meetany_private.fail('MA622'); end if;
 if jsonb_array_length(p_items)>100 then perform meetany_private.fail('MA622'); end if;
 for item in select value from jsonb_array_elements(p_items) loop
  if jsonb_typeof(item)<>'object' or jsonb_typeof(item->'name') is distinct from 'string' or length(trim(item->>'name')) not between 2 and 80
   or (item ? 'photoUrl' and jsonb_typeof(item->'photoUrl') not in ('string','null'))
   or (coalesce(item->>'photoUrl','')<>'' and
       (not coalesce(meetany_private.valid_photo_url(item->>'photoUrl',me.id),false)
        or not coalesce(item->>'photoUrl'=any(me.gallery),false)))
   or (item ? 'note' and jsonb_typeof(item->'note')<>'string') or length(coalesce(item->>'note',''))>200
   or (item ? 'code' and (jsonb_typeof(item->'code')<>'string' or length(item->>'code')>40))
   or (item ? 'unit' and (jsonb_typeof(item->'unit')<>'string' or item->>'unit' not in ('pcs','m2','kg','hour','service','m','l','set','pack')))
   or (item ? 'price' and jsonb_typeof(item->'price')<>'number')
  then perform meetany_private.fail('MA622'); end if;
  -- Cast only after checking the JSON type, so malformed prices also produce MA622.
  if item ? 'price' and ((item->>'price')::numeric<0 or (item->>'price')::numeric>1000000000)
  then perform meetany_private.fail('MA622'); end if;
  product:=jsonb_build_object('name',trim(item->>'name'),'photoUrl',item->>'photoUrl','note',trim(coalesce(item->>'note','')));
  if item ? 'code' then product:=product||jsonb_build_object('code',item->>'code'); end if;
  if item ? 'unit' then product:=product||jsonb_build_object('unit',item->>'unit'); end if;
  if item ? 'price' then product:=product||jsonb_build_object('price',item->'price'); end if;
  cleaned:=cleaned||jsonb_build_array(product);
 end loop;
 insert into meetany_private.company_products(company_id,items) values(me.id,cleaned) on conflict(company_id) do update set items=excluded.items;
 return cleaned;
end $function$

CREATE OR REPLACE FUNCTION public.set_notification_email(p_enabled boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_user();
begin
 if p_enabled is null then raise exception using errcode='22023',message='enabled is required'; end if;
 insert into meetany_private.notification_preferences(user_id,email_offers) values(me.id,p_enabled)
 on conflict(user_id) do update set email_offers=excluded.email_offers;
 if not p_enabled then
  update meetany_private.notification_outbox set status='cancelled',lease_id=null,locked_until=null
  where status in ('pending','processing') and notification_id in(select id from meetany_private.notifications where user_id=me.id);
 end if;
 return p_enabled;
end $function$

CREATE OR REPLACE FUNCTION public.set_offer_terms(p_offer_id uuid, p_payment_terms text, p_valid_until date, p_commercial_terms text[], p_expected_updated_at timestamp with time zone)
 RETURNS offers
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_user(); o public.offers; r public.requests;
begin
 select * into o from public.offers where id=p_offer_id and company_id=me.id;
 if not found then perform meetany_private.flow_fail('MA901'); end if;
 select * into r from public.requests where id=o.request_id for update;
 select * into o from public.offers where id=p_offer_id for update;
 if o.id is null or meetany_private.request_state(r)<>'open' then perform meetany_private.flow_fail('MA903'); end if;
 if p_expected_updated_at is null or o.updated_at<>p_expected_updated_at then perform meetany_private.flow_fail('MA904'); end if;
 if (p_payment_terms is not null and length(btrim(p_payment_terms)) not between 1 and 500)
 or (p_valid_until is not null and (not isfinite(p_valid_until) or p_valid_until<meetany_private.today()))
 or p_commercial_terms is null or not meetany_private.valid_items(p_commercial_terms) then perform meetany_private.flow_fail('MA902'); end if;
 update public.offers set payment_terms=btrim(p_payment_terms),valid_until=p_valid_until,commercial_terms=p_commercial_terms,updated_at=clock_timestamp() where id=o.id returning * into o;
 return o;
end $function$

CREATE OR REPLACE FUNCTION public.set_request_alert_preferences(p_enabled boolean, p_categories text[], p_cities text[], p_email_mode text DEFAULT 'off'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_user(); cats text[]; towns text[]; changed boolean;
begin
 if me.role<>'company' then perform meetany_private.fail('MA201'); end if;
 if p_enabled is null or p_email_mode is null or p_email_mode not in ('off','instant','daily')
 or p_categories is null or p_cities is null or cardinality(p_categories)>cardinality(meetany_private.categories()) or cardinality(p_cities)>8
 or array_position(p_categories,null) is not null or array_position(p_cities,null) is not null
 or not p_categories <@ meetany_private.categories() or not p_cities <@ meetany_private.cities() then
  raise exception using errcode='22023',message='invalid request alert preferences';
 end if;
 select coalesce(array_agg(distinct x order by x),'{}') into cats from unnest(p_categories) x;
 select coalesce(array_agg(distinct x order by x),'{}') into towns from unnest(p_cities) x;
 if 'georgia'=any(towns) then towns:=array['georgia']; end if;
 if p_enabled and (cardinality(cats)=0 or cardinality(towns)=0) then raise exception using errcode='22023',message='select categories and cities'; end if;
 insert into meetany_private.request_alert_preferences(user_id,enabled,categories,cities,email_mode)
 values(me.id,p_enabled,cats,towns,p_email_mode)
 on conflict(user_id) do update set enabled=excluded.enabled,categories=excluded.categories,cities=excluded.cities,email_mode=excluded.email_mode,generation=gen_random_uuid()
 where (request_alert_preferences.enabled,request_alert_preferences.categories,request_alert_preferences.cities,request_alert_preferences.email_mode)
 is distinct from (excluded.enabled,excluded.categories,excluded.cities,excluded.email_mode)
 returning true into changed;
 -- A preference change cancels queued delivery, not existing inbox history. No backfill.
 update meetany_private.request_alert_emails set status='cancelled',lease_id=null,locked_until=null
 where changed and user_id=me.id and status in ('pending','processing');
 return public.request_alert_preferences();
end $function$

CREATE OR REPLACE FUNCTION public.set_request_preferences(p_request_id uuid, p_preferences jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_user(); r public.requests; p jsonb:=p_preferences;
begin
 select * into r from public.requests where id=p_request_id and owner_id=me.id for update;
 if not found then perform meetany_private.flow_fail('MA901'); end if;
 if meetany_private.request_state(r)<>'open' then perform meetany_private.flow_fail('MA903'); end if;
 if p is null or jsonb_typeof(p)<>'object' or octet_length(p::text)>12000 or exists(select 1 from jsonb_object_keys(p) k where k not in('specification','design','supplierTypes','certificates','verifiedOnly','flexibility','budgetType','budgetMin','budgetMax','budgetPrivate','payment','vatInvoice','deferredPayment')) then perform meetany_private.flow_fail('MA902'); end if;
 if exists(select 1 from jsonb_each(p) x where x.key in('specification','design','certificates','payment') and jsonb_typeof(x.value)<>'string') then perform meetany_private.flow_fail('MA902'); end if;
 if p ? 'design' and p->>'design' not in('','ready','needed','none') then perform meetany_private.flow_fail('MA902'); end if;
 if length(coalesce(p->>'specification',''))>2000 or length(coalesce(p->>'design',''))>120 or length(coalesce(p->>'payment',''))>500 or length(coalesce(p->>'certificates',''))>500 then perform meetany_private.flow_fail('MA902'); end if;
 if p ? 'flexibility' and (jsonb_typeof(p->'flexibility')<>'number' or (p->>'flexibility')::numeric not between 0 and 30) then perform meetany_private.flow_fail('MA902'); end if;
 if p ? 'supplierTypes' and (jsonb_typeof(p->'supplierTypes')<>'array' or jsonb_array_length(p->'supplierTypes')>3 or exists(select 1 from jsonb_array_elements_text(p->'supplierTypes') t where t not in('manufacturer','distributor','service'))) then perform meetany_private.flow_fail('MA902'); end if;
 if coalesce(p->>'budgetType','negotiable') not in('range','exact','negotiable') then perform meetany_private.flow_fail('MA902'); end if;
 if exists(select 1 from jsonb_each(p) x where x.key in('budgetMin','budgetMax') and (jsonb_typeof(x.value)<>'number' or (x.value::text)::numeric not between 0 and 1000000000)) then perform meetany_private.flow_fail('MA902'); end if;
 if coalesce(p->>'budgetType','negotiable')<>'negotiable' and (not p ? 'budgetMin' or (p->>'budgetMin')::numeric<=0 or (p->>'budgetType'='range' and (not p ? 'budgetMax' or (p->>'budgetMax')::numeric<(p->>'budgetMin')::numeric))) then perform meetany_private.flow_fail('MA902'); end if;
 if exists(select 1 from jsonb_each(p) x where x.key in('budgetPrivate','verifiedOnly','vatInvoice','deferredPayment') and jsonb_typeof(x.value)<>'boolean') then perform meetany_private.flow_fail('MA902'); end if;
 insert into meetany_private.request_preferences(request_id,preferences) values(r.id,p) on conflict(request_id) do update set preferences=excluded.preferences;
 update public.requests set
  budget_type=case when p->>'budgetType' in('range','exact') and not coalesce((p->>'budgetPrivate')::boolean,false) then p->>'budgetType' end,
  budget_min=case when p->>'budgetType' in('range','exact') and not coalesce((p->>'budgetPrivate')::boolean,false) then (p->>'budgetMin')::numeric end,
  budget_max=case when p->>'budgetType'='range' and not coalesce((p->>'budgetPrivate')::boolean,false) then (p->>'budgetMax')::numeric end
 where id=r.id;
 return p;
end $function$

CREATE OR REPLACE FUNCTION public.set_saved_company(p_company_id uuid, p_saved boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare me public.profiles:=meetany_private.require_user();
begin
 if p_saved is null then raise exception using errcode='22023',message='saved is required'; end if;
 if not p_saved then delete from meetany_private.saved_companies where user_id=me.id and company_id=p_company_id; return false; end if;
 if not exists(select 1 from public.profiles where id=p_company_id and role='company' and not blocked) then perform meetany_private.fail('MA302'); end if;
